const C = {...THEMES.dark}
function applyTheme(key){
  const t = THEMES[key] || THEMES.dark
  Object.assign(C, t)
  document.body.style.background = t.bg
  document.body.style.color = t.text
  try{ localStorage.setItem('lakshmimata-theme', key) }catch(e){}
}

