// ── Weinstein Stage Detection ─────────────────────────────────────────
// Stage 1: Basing — price flat near lows, RS weak/flat
// Stage 2: Uptrend — price above 30W MA, RS improving/strong ← best buys
// Stage 3: Topping — price extended above MA, RS may be declining
// Stage 4: Downtrend — price below 30W MA, RS declining
function calcWeinsteinStage(s){
  const rs = s.rs || 0
  const trend = s.rsTrend?.trend || 'flat'
  const chg = s.chg || 0
  const pctFromHigh = s.pctFromHigh || 0  // negative = below high
  const hist = s.hist || []
  const recentRS = hist.filter(Boolean).slice(-5)
  const avgRecentRS = recentRS.length ? recentRS.reduce((a,b)=>a+b,0)/recentRS.length : rs

  // Stage 2: Strong RS + improving trend + not too extended
  if(rs >= 70 && (trend === 'improving' || trend === 'flat') && pctFromHigh >= -30){
    if(pctFromHigh >= -5) return {stage:3, label:'S3 Top', color:C.orange, desc:'Topping — extended'}
    return {stage:2, label:'S2 Up', color:C.green, desc:'Uptrend — best buys'}
  }
  // Stage 3: High RS but declining
  if(rs >= 70 && trend === 'declining'){
    return {stage:3, label:'S3 Top', color:C.orange, desc:'Topping — RS declining'}
  }
  // Stage 4: Weak RS + declining
  if(rs < 40 && (trend === 'declining' || avgRecentRS < 40)){
    return {stage:4, label:'S4 Down', color:C.red, desc:'Downtrend — avoid'}
  }
  // Stage 1: Weak/flat RS, flat trend, near lows
  if(rs < 50 && trend === 'flat'){
    return {stage:1, label:'S1 Base', color:C.yellow, desc:'Basing — watch for breakout'}
  }
  // Default: Stage 1/2 transition
  if(rs >= 50 && rs < 70){
    return {stage:2, label:'S2 Early', color:C.teal, desc:'Early uptrend'}
  }
  return {stage:1, label:'S1 Base', color:C.yellow, desc:'Basing'}
}

// ── Volume vs Average ─────────────────────────────────────────────────
// pctOfMax = today's volume as a % of the recent peak-volume day (NOT a
// price high/low, even though the labels below read that way at a
// glance — kept short for table width, see VolBadge for the fuller
// "X% of peak" wording shown next to it).
function calcVolAnalysis(s){
  const vol = s.hy?.todayVol || 0
  const pctOfMax = s.hy?.pctOfMax || 0
  // Classify volume
  if(pctOfMax >= 95) return {label:'🔥 Vol Surge', color:C.orange, pct:pctOfMax}
  if(pctOfMax >= 70) return {label:'Vol: High', color:C.green, pct:pctOfMax}
  if(pctOfMax >= 40) return {label:'Vol: Avg', color:C.muted, pct:pctOfMax}
  return {label:'Vol: Low', color:C.red, pct:pctOfMax}
}

// ── IBV Detection (Institutional Buying Volume) ──────────────────────
// 3+ big up days with volume > down days volume in last 10 days
function calcIBV(s){
  const rs = s.rs || 0
  const trend = s.rsTrend?.trend || 'flat'
  const ppCount = s.pp?.ppCount10d || 0
  const chg = s.chg || 0

  const ibvScore = (ppCount >= 3 ? 3 : ppCount) +
                   (trend === 'improving' ? 2 : 0) +
                   (chg > 0 ? 1 : 0) +
                   (rs >= 70 ? 1 : 0)

  const isIBV = s.ibvSignal === true
  return {
    isIBV,
    ibvScore,
    ppCount,
    label: isIBV ? '🏛️ IBV' : 'No IBV',
    color: isIBV ? C.purple : C.muted,
    desc: 'Institutional-style volume activity detected'
  }
}

// A stock can technically have HT, HY, IBV, and PP all true at once
// (they're independent volume checks) — but showing all four badges on
// one card is redundant, and HT/HY/IBV are all stronger signals than
// PP specifically, so only the single highest-priority one should
// actually be surfaced anywhere (badges, filters, counts, Breakout tab
// sections), matching the same HT > HY > IBV > PP priority already
// used for the chart's volume bar coloring. Module-level (not inside
// App) so every component that needs it — including ones outside
// App's closure, like PresetFilterBar — can call it directly.
function topVolumeSignal(s){
  if(s.ht?.isHT) return 'ht'
  if(s.hy?.isHY) return 'hy'
  if(calcIBV(s).isIBV) return 'ibv'
  if(s.pp?.isPP) return 'pp'
  return null
}

// True if the last-10-days boolean history has at least `n` Pocket
// Pivots occurring on consecutive trading days anywhere in the window
// — back-to-back accumulation days, not just scattered PP days.
function hasConsecutivePP(ppHistory, n=2){
  if(!ppHistory || ppHistory.length===0) return false
  let streak = 0
  for(const isOn of ppHistory){
    streak = isOn ? streak+1 : 0
    if(streak >= n) return true
  }
  return false
}

// ── HY/HT Breakout Scanner ────────────────────────────────────────────
// Had HY or HT in last 5 days + price breaking out today
function calcHYHTBreakout(s){
  const ppHist = s.pp?.ppHistory || []
  const rs = s.rs || 0
  const chg = s.chg || 0
  const trend = s.rsTrend?.trend || 'flat'

  // Recent HY/HT signal = PP in last 5 days (proxy for high volume event)
  const recentPP = ppHist.slice(-5).some(Boolean)
  const todayPP  = ppHist[ppHist.length-1] || false
  const isHY     = s.hy?.isHY || false
  const isHT     = s.ht?.isHT || false

  // Breakout conditions:
  // 1. Had HY or HT in last 5 days
  // 2. Price is up today (breaking out)
  // 3. RS is strong
  const hadRecentHighVol = recentPP || isHY || isHT
  const priceBreaking    = chg > 1.0   // price up > 1% today
  const rsStrong         = rs >= 60
  const isBreakout       = hadRecentHighVol && priceBreaking && rsStrong

  // Breakout strength
  let strength = 'Weak'
  let color    = C.muted
  if(isBreakout){
    if(rs >= 80 && chg >= 3)  { strength = '🚀 Power'; color = C.accent }
    else if(rs >= 70 && chg >= 2){ strength = '⭐ Strong'; color = C.green }
    else                         { strength = '✅ Valid';  color = C.teal }
  }

  return {
    isBreakout,
    hadRecentHighVol,
    priceBreaking,
    strength,
    color,
    chg: chg.toFixed(2),
    recentPPCount: ppHist.slice(-5).filter(Boolean).length,
    isHY,
    isHT,
    desc: isBreakout
      ? `${strength} breakout — +${chg.toFixed(1)}% with recent high vol`
      : 'No breakout signal'
  }
}

// ── Vol climax → EMA pullback (entry) ─────────────────────────────────
// After HY / HT / IBV / Bull Snort in the last ~10 days, price has pulled
// back to within ~3% of EMA5, EMA9, EMA21, or EMA50 — buy-the-dip zone.
function recentBullSnort(s, lookback=10){
  if(s.isBullSnort) return true
  const closes = s.prices
  const volumes = s.volumes
  if(!closes?.length || !volumes?.length) return false
  const flags = detectBullSnortDays(
    s.highs || closes, s.lows || closes, closes, volumes, s.opens
  )
  return flags.slice(-lookback).some(Boolean)
}
function calcVolClimaxNearSupport(s, lookback=10){
  const hyHist = s.hy?.history || []
  const htHist = s.ht?.history || []
  const ibvHist = s.ibvHistory || []
  const recentHY = !!(s.hy?.isHY) || hyHist.slice(-lookback).some(Boolean)
  const recentHT = !!(s.ht?.isHT) || htHist.slice(-lookback).some(Boolean)
  const recentIBV = !!calcIBV(s).isIBV || ibvHist.slice(-lookback).some(Boolean)
  const recentSnort = recentBullSnort(s, lookback)
  const hadRecentClimax = recentHY || recentHT || recentIBV || recentSnort

  const nearEma5 = !!s.nearEMA5?.isNearEMA5
  const nearEma9 = !!s.nearEMA9?.isNearEMA9
  const nearEma21 = !!s.nearEMA21?.isNearEMA21
  const nearEma50 = !!s.nearEMA50?.isNearEMA50
  const nearPullback = nearEma5 || nearEma9 || nearEma21 || nearEma50

  const isMatch = hadRecentClimax && nearPullback
  const tags = []
  if(recentHY) tags.push('HY')
  if(recentHT) tags.push('HT')
  if(recentIBV) tags.push('IBV')
  if(recentSnort) tags.push('Snort')
  const near = []
  if(nearEma5) near.push('EMA5')
  if(nearEma9) near.push('EMA9')
  if(nearEma21) near.push('EMA21')
  if(nearEma50) near.push('EMA50')

  return {
    isMatch,
    hadRecentClimax,
    nearSupport: nearPullback,
    recentHY, recentHT, recentIBV, recentSnort,
    nearEma5, nearEma9, nearEma21, nearEma50,
    nearIbv: !!calcIBV(s).isIBV,
    nearHyHt: !!(s.hy?.isHY) || !!(s.ht?.isHT),
    label: isMatch ? `🔥→⚡ ${tags.join('/')} · ${near.join('/')}` : null,
    desc: isMatch
      ? `Recent ${tags.join('/')} pullback to ${near.join(' / ')} — watch for bounce`
      : 'Need recent HY/HT/IBV/Bull Snort AND price near EMA5, EMA9, EMA21, or EMA50',
  }
}

// ── HY/HT/IBV → low-vol sell → EMA5/9/21 bounce ───────────────────────
// Recent volume climax (HY / HT / IBV), quiet pullback, then reverses today
// while holding the 5-, 9-, or 21-day EMA (CHENNPETRO-style, broadened).
function calcHyLowVolEma9Bounce(s, lookback=10){
  const hyHist = s.hy?.history || []
  const htHist = s.ht?.history || []
  const ibvHist = s.ibvHistory || []

  const histBefore = (hist) => hist.length > 1 && hist.slice(-lookback, -1).some(Boolean)
  const histToday = (hist) => !!(hist.length && hist.slice(-lookback).slice(-1)[0])

  const hyBefore = histBefore(hyHist)
  const htBefore = histBefore(htHist)
  const ibvBefore = histBefore(ibvHist)
  const hyToday = !!(s.hy?.isHY) || histToday(hyHist)
  const htToday = !!(s.ht?.isHT) || histToday(htHist)
  const ibvToday = !!calcIBV(s).isIBV || histToday(ibvHist)

  const recentHY = hyBefore || hyToday
  const recentHT = htBefore || htToday
  const recentIBV = ibvBefore || ibvToday
  const hadClimax = recentHY || recentHT || recentIBV
  const climaxBeforeToday = hyBefore || htBefore || ibvBefore

  const last = s.last
  const nearPct = (ema, storedPct, storedNear) => {
    if(ema && last){
      const pct = +((last - ema) / ema * 100).toFixed(2)
      return { near: Math.abs(pct) <= 3, pct }
    }
    return { near: !!storedNear, pct: storedPct ?? null }
  }
  // No RS-90 gate — structure pattern, not elite-RS-only.
  const e5 = nearPct(s.nearEMA5?.ema5, s.nearEMA5?.pctFromEMA5, s.nearEMA5?.isNearEMA5)
  const e9 = nearPct(s.nearEMA9?.ema9, s.nearEMA9?.pctFromEMA9, s.nearEMA9?.isNearEMA9)
  const e21 = nearPct(s.nearEMA21?.ema21, s.nearEMA21?.pctFromEMA21, s.nearEMA21?.isNearEMA21)
  const nearEma5 = e5.near
  const nearEma9 = e9.near
  const nearEma21 = e21.near
  const nearEma = nearEma5 || nearEma9 || nearEma21
  const nearTags = []
  if(nearEma5) nearTags.push('EMA5')
  if(nearEma9) nearTags.push('EMA9')
  if(nearEma21) nearTags.push('EMA21')

  const bounce = (s.chg ?? 0) >= 0
  const rvol = s.rvol
  const volSignal = s.volSignal
  const lowVol = (rvol != null && rvol < 0.85)
    || volSignal === 'dry'
    || volSignal === 'avg'
    || (rvol == null && volSignal == null)

  const soldAfterClimax = climaxBeforeToday || ((s.chgW ?? 0) < 0 && hadClimax)

  // When full OHLCV exists, require quiet down-days after the last climax bar.
  let quietSellConfirmed = null
  const prices = s.prices
  const volumes = s.volumes
  if(Array.isArray(prices) && Array.isArray(volumes) && prices.length >= 25 && volumes.length === prices.length){
    const n = prices.length
    const start = Math.max(0, n - lookback)
    let lastClimax = -1
    for(let i = n - 1; i >= start; i--){
      const off = hyHist.length - (n - i)
      const hy = (off >= 0 && hyHist[off]) || (i === n - 1 && s.hy?.isHY)
      const htOff = htHist.length - (n - i)
      const ht = (htOff >= 0 && htHist[htOff]) || (i === n - 1 && s.ht?.isHT)
      const ibvOff = ibvHist.length - (n - i)
      const ibv = (ibvOff >= 0 && ibvHist[ibvOff]) || (i === n - 1 && calcIBV(s).isIBV)
      if(hy || ht || ibv){ lastClimax = i; break }
    }
    if(lastClimax >= 0 && lastClimax < n - 1){
      let downQuiet = 0, downDays = 0
      for(let i = lastClimax + 1; i < n - 1; i++){
        if(prices[i] == null || prices[i - 1] == null) continue
        if(prices[i] >= prices[i - 1]) continue
        downDays++
        const win = volumes.slice(Math.max(0, i - 20), i)
        const avg = win.length ? win.reduce((a,b)=>a+(b||0),0) / win.length : 0
        if(avg > 0 && (volumes[i] || 0) < avg * 0.55) downQuiet++
      }
      quietSellConfirmed = downDays === 0 ? false : (downQuiet / downDays) >= 0.5
    }
  }

  const quietOk = quietSellConfirmed == null ? lowVol : quietSellConfirmed
  const climaxTags = []
  if(recentHY) climaxTags.push('HY')
  if(recentHT) climaxTags.push('HT')
  if(recentIBV) climaxTags.push('IBV')

  const isMatch = hadClimax && soldAfterClimax && nearEma && bounce && quietOk

  return {
    isMatch,
    hadClimax, recentHY, recentHT, recentIBV,
    nearEma5, nearEma9, nearEma21, nearEma, bounce, quietOk,
    pctFromEMA5: e5.pct,
    pctFromEMA9: e9.pct,
    pctFromEMA21: e21.pct,
    hadHY: recentHY,
    rvol,
    label: isMatch ? `🔥→⚡ ${climaxTags.join('/')}·low-vol→${nearTags.join('/')}` : null,
    desc: isMatch
      ? `Recent ${climaxTags.join('/')} quiet pullback, bounce at ${nearTags.join(' / ')}`
      : 'Need recent HY/HT/IBV, low-volume sell, and a bounce holding EMA5, EMA9, or EMA21',
  }
}

