// Shows the 10-day dot history for whichever volume signal is actually
// this stock's top priority (HT > HY > IBV > PP) — instead of always
// hardcoding "PP 10d" even for a stock whose real signal is HT, which
// was inconsistent with the badge shown above it.
// One row of dots covering all four signals at once — each day's dot
// is colored by whichever signal fired that day (priority HT > HY >
// IBV > PP if more than one fired the same day, matching the same
// priority used for the chart's volume-bar coloring), instead of
// either stacking all four histories or only showing one signal type
// for the whole stock.
function MergedSignalDots({s}){
  const ht  = s.ht?.history || []
  const hy  = s.hy?.history || []
  const ibv = s.ibvHistory || []
  const pp  = s.pp?.ppHistory || []
  const len = Math.max(ht.length, hy.length, ibv.length, pp.length, 10)
  const dots = Array.from({length: len}, (_, i) => {
    if (ht[i])  return {color:C.orange, label:'HT'}
    if (hy[i])  return {color:C.pink,   label:'HY'}
    if (ibv[i]) return {color:C.blue,   label:'IBV'}
    if (pp[i])  return {color:C.green,  label:'PP'}
    return {color:null, label:null}
  })
  return(
    <div style={{display:'flex',gap:2,alignItems:'center'}}>
      {dots.map((d,i)=>{
        const dIdx = dots.length-1-i
        const isToday = dIdx===0
        return <div key={i} title={`${isToday?'Today':`${dIdx}d ago`}: ${d.label||'No signal'}`}
          style={{width:isToday?11:8,height:isToday?11:8,flexShrink:0,borderRadius:'50%',
            background:d.color||C.border,
            border:isToday?`1.5px solid ${C.text}`:'none',
            boxShadow:d.color?`0 0 4px ${d.color}`:'none'}}/>
      })}
    </div>
  )
}
// Parses a brokerage holdings export (Zerodha Console, Dhan, Groww,
// Upstox, ICICI Direct, Angel One, etc.) into {sym, qty, entryPrice} rows.
// Every brokerage names its columns differently, so instead of requiring
// one fixed template, this scores each column header against a keyword set
// per field and picks whichever header matches best — works across
// exports without the person needing to reformat anything first.
const SYMBOL_COL_HINTS = ['tradingsymbol','trading symbol','symbol','instrument','stock symbol','scrip','security id','security']
const NAME_COL_HINTS = ['company name','stock name','security name','name of company','company','name','isin name']
const QTY_COL_HINTS = ['qty', 'quantity', 'net qty', 'shares', 'holding qty', 'available quantity', 'net quantity', 'free qty']
const PRICE_COL_HINTS = ['avg. cost', 'avg cost', 'average price', 'avg price', 'average buy price',
  'buy avg', 'avg. cost price', 'average cost', 'purchase price', 'buy price', 'avg buy price', 'average']

function bestColumnMatch(headers, hints){
  let best=null, bestScore=-1
  for(const h of headers){
    const hl = String(h).toLowerCase().trim()
    for(const hint of hints){
      if(hl===hint){ return h } // exact match wins immediately
      if(hl.includes(hint) && hint.length>bestScore){ best=h; bestScore=hint.length }
    }
  }
  return best
}

/** Prefer brokerage company name, then static master name, then industry/sector. */
function portfolioDisplayName(holding, stock){
  const fromFile = (holding?.name || '').trim()
  if (fromFile && fromFile.toUpperCase() !== holding?.sym) return fromFile
  return stock?.name || getCompanyName(holding?.sym || stock?.sym) || stock?.industry || stock?.sector || null
}

function findIndexRow(indexData, names){
  if (!indexData?.length) return null
  for (const name of names) {
    const exact = indexData.find(i => i.name === name)
    if (exact) return exact
    const fuzzy = indexData.find(i =>
      String(i.name||'').toLowerCase().includes(String(name).toLowerCase()))
    if (fuzzy) return fuzzy
  }
  return null
}

/** Value-weighted (else equal-weight) average of a stock field across holdings. */
function portfolioWeightedAvg(holdings, stocks, field){
  let sumW = 0, sum = 0
  for (const h of holdings) {
    const s = stocks.find(x => x.sym === h.sym)
    if (!s || s[field] == null || !isFinite(s[field])) continue
    const w = (h.qty && s.last) ? h.qty * s.last : 1
    sum += s[field] * w
    sumW += w
  }
  return sumW > 0 ? sum / sumW : null
}

/**
 * Quiet portfolio structure flags — technical state only.
 * Never use buy/sell/exit wording (SEBI: not investment advice).
 * rank: lower = more urgent (for attention strip / sort).
 */
function portfolioHoldingHealth(s, pnlPct){
  const stage = s ? calcWeinsteinStage(s) : null
  const rs = s?.rsTv ?? s?.rs ?? null
  const trend = s?.rsTrend?.trend || 'flat'
  const loss = pnlPct!=null && isFinite(pnlPct) ? pnlPct : null

  if(stage?.stage===4 || (rs!=null && rs<25 && (loss==null || loss<0))){
    return {key:'exit', label:'Caution', short:'Caution', color:C.red, rank:0,
      tip: 'Technical: Stage 4 / very weak RS vs market — educational flag only, not a sell call'}
  }
  if(stage?.stage===3 || (rs!=null && rs>=70 && trend==='declining')){
    return {key:'watch', label:'Extended', short:'Extended', color:C.orange, rank:1,
      tip: 'Technical: Stage 3 / RS fading — educational flag only, not investment advice'}
  }
  if((rs!=null && rs<40) || (loss!=null && loss<=-12)){
    return {key:'weak', label:'Lagging', short:'Lagging', color:C.red, rank:2,
      tip: loss!=null && loss<=-12
        ? 'Technical: deep drawdown vs your cost — for your review only'
        : 'Technical: RS lagging the market — educational flag only'}
  }
  if(stage?.stage===2 && rs!=null && rs>=70 && (loss==null || loss>=0)){
    return {key:'strong', label:'Leading', short:'Leading', color:C.green, rank:4,
      tip: 'Technical: Stage 2 + strong RS — educational flag only, not a buy/hold call'}
  }
  return {key:'ok', label:'Neutral', short:'Neutral', color:C.muted, rank:3,
    tip: stage?.desc || 'No urgent technical flag'}
}

