const MAX_FAMILY_PORTFOLIOS = 5
const PORTFOLIOS_KEY = 'lm_portfolios'
const PORTFOLIO_LEGACY_KEY = 'lm_portfolio'
const PORTFOLIO_ACTIVE_KEY = 'lm_portfolio_active'

function newPortfolioId(){
  return 'p_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7)
}

function normalizePortfoliosPayload(raw){
  const list=(Array.isArray(raw?.portfolios)?raw.portfolios:[])
    .slice(0,MAX_FAMILY_PORTFOLIOS)
    .map(p=>({
      id:p?.id||newPortfolioId(),
      name:String(p?.name||'Portfolio').trim().slice(0,40)||'Portfolio',
      holdings:Array.isArray(p?.holdings)?p.holdings:[],
    }))
  if(!list.length) return null
  let activeId=raw?.activeId||raw?.active_id||list[0].id
  if(!list.some(p=>p.id===activeId)) activeId=list[0].id
  return {portfolios:list, activeId}
}

function persistPortfoliosLocal({portfolios, activeId}){
  const payload={portfolios, activeId}
  try{
    localStorage.setItem(PORTFOLIOS_KEY, JSON.stringify(payload))
    localStorage.setItem(PORTFOLIO_ACTIVE_KEY, activeId||'')
    const active=portfolios.find(p=>p.id===activeId)||portfolios[0]
    localStorage.setItem(PORTFOLIO_LEGACY_KEY, JSON.stringify(active?.holdings||[]))
  }catch{/* ignore quota */}
}

/** Load family portfolios (max 5). Migrates legacy single lm_portfolio array. */
function loadPortfoliosState(){
  try{
    const raw=JSON.parse(localStorage.getItem(PORTFOLIOS_KEY)||'null')
    const normalized=normalizePortfoliosPayload(raw)
    if(normalized) return normalized
  }catch{/* ignore */}
  let holdings=[]
  try{
    const legacy=JSON.parse(localStorage.getItem(PORTFOLIO_LEGACY_KEY)||'[]')
    if(Array.isArray(legacy)) holdings=legacy
  }catch{/* ignore */}
  const id=newPortfolioId()
  return {portfolios:[{id, name:'My Portfolio', holdings}], activeId:id}
}

// Cleans a brokerage's raw symbol text into the plain NSE ticker this
// app uses — strips exchange prefixes ("NSE:", "BSE:"), "-EQ"/"-BE"
// series suffixes some brokers append, and surrounding whitespace.
function normalizeSymbol(raw){
  if(!raw) return null
  let s = String(raw).trim().toUpperCase()
  s = s.replace(/^(NSE|BSE)[:\-]\s*/,'')
  s = s.replace(/-(EQ|BE|BZ|BL)$/,'')
  return s || null
}

function parseBrokerageHoldingsFile(file){
  return new Promise((resolve, reject)=>{
    const reader = new FileReader()
    reader.onerror = ()=>reject(new Error('Could not read the file'))
    reader.onload = (e)=>{
      try{
        const wb = XLSX.read(e.target.result, {type:'binary'})
        const sheet = wb.Sheets[wb.SheetNames[0]]
        const rows = XLSX.utils.sheet_to_json(sheet, {defval:null})
        if(!rows.length){ resolve({holdings:[], skipped:[]}); return }

        const headers = Object.keys(rows[0])
        const symCol   = bestColumnMatch(headers, SYMBOL_COL_HINTS)
        const nameCol  = bestColumnMatch(headers.filter(h=>h!==symCol), NAME_COL_HINTS)
        const qtyCol   = bestColumnMatch(headers, QTY_COL_HINTS)
        const priceCol = bestColumnMatch(headers, PRICE_COL_HINTS)

        if(!symCol){
          reject(new Error(`Couldn't find a symbol/instrument column. Columns found: ${headers.join(', ')}`))
          return
        }

        const holdings = [], skipped = []
        for(const row of rows){
          const sym = normalizeSymbol(row[symCol])
          if(!sym){ continue }
          const qty = qtyCol ? Number(row[qtyCol]) : null
          const entryPrice = priceCol ? Number(row[priceCol]) : null
          const rawName = nameCol != null ? String(row[nameCol] ?? '').trim() : ''
          if(qtyCol && (qty==null || isNaN(qty))){ skipped.push(sym); continue }
          holdings.push({
            sym,
            name: (rawName && rawName.toUpperCase() !== sym ? rawName : null) || getCompanyName(sym) || null,
            qty: (qty!=null && !isNaN(qty)) ? qty : null,
            entryPrice: (entryPrice!=null && !isNaN(entryPrice)) ? entryPrice : null,
          })
        }
        resolve({holdings, skipped, matchedCols:{symCol, nameCol, qtyCol, priceCol}})
      }catch(err){
        reject(err)
      }
    }
    reader.readAsBinaryString(file)
  })
}

