function SectorLeadersLaggards({sectorData, onViewAll}) {
  if (!sectorData?.length) {
    return (
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:'10px 12px',height:'100%'}}>
        <div style={{fontWeight:700,fontSize:12,color:C.text,marginBottom:6}}>Sector RS</div>
        <div style={{fontSize:11,color:C.muted}}>Sector data loading…</div>
      </div>
    )
  }
  const sorted = [...sectorData].sort((a,b)=>(a.rank??999)-(b.rank??999))
  const top = sorted.slice(0,3)
  const bottom = [...sorted].reverse().slice(0,3)
  const row = (sec, accent) => (
    <div key={sec.sector} style={{display:'flex',alignItems:'center',gap:8,padding:'5px 0',
      borderBottom:`1px solid ${C.border}33`}}>
      <span style={{fontSize:11,fontWeight:600,color:C.text,flex:1,minWidth:0,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
        {sec.sector}
      </span>
      <span style={{fontSize:10,color:C.muted}}>#{sec.rank}</span>
      <span style={{fontSize:12,fontWeight:800,color:rsColor(sec.avgRS),minWidth:28,textAlign:'right'}}>{sec.avgRS}</span>
      <span style={{fontSize:8,fontWeight:700,color:accent,width:8}}>●</span>
    </div>
  )
  return (
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:'10px 12px',height:'100%'}}>
      <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:8}}>
        <div style={{fontWeight:700,fontSize:12,color:C.text}}>Sector RS</div>
        {onViewAll&&(
          <button onClick={onViewAll}
            style={{marginLeft:'auto',fontSize:10,fontWeight:600,color:C.accent,background:'transparent',
              border:'none',cursor:'pointer',padding:0}}>
            All sectors →
          </button>
        )}
      </div>
      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12}}>
        <div>
          <div style={{fontSize:9,fontWeight:700,color:C.green,marginBottom:4,textTransform:'uppercase'}}>Leaders</div>
          {top.map(s=>row(s,C.green))}
        </div>
        <div>
          <div style={{fontSize:9,fontWeight:700,color:C.red,marginBottom:4,textTransform:'uppercase'}}>Laggards</div>
          {bottom.map(s=>row(s,C.red))}
        </div>
      </div>
    </div>
  )
}

function StageDistributionBar({stocks}) {
  if (!stocks?.length) return null
  const stages = [
    {n:1, label:'S1 Base', color:C.yellow},
    {n:2, label:'S2 Up', color:C.green},
    {n:3, label:'S3 Top', color:C.orange},
    {n:4, label:'S4 Down', color:C.red},
  ]
  const counts = stages.map(s => ({
    ...s,
    name: s.label,
    value: stocks.filter(st => calcWeinsteinStage(st).stage === s.n).length,
  }))
  const tot = stocks.length
  const pieData = counts.filter(s => s.value > 0)
  return (
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:'10px 12px',marginBottom:10}}>
      <div style={{display:'flex',alignItems:'baseline',gap:8,marginBottom:8,flexWrap:'wrap'}}>
        <div style={{fontWeight:700,fontSize:12,color:C.text}}>Weinstein Stage Mix</div>
        <div style={{fontSize:10,color:C.muted}}>{tot} stocks</div>
      </div>
      <div style={{display:'flex',alignItems:'center',gap:14,flexWrap:'wrap'}}>
        <div style={{width:148,height:148,flexShrink:0}}>
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={pieData}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                innerRadius={38}
                outerRadius={66}
                paddingAngle={1.5}
                stroke={C.card}
                strokeWidth={1}
              >
                {pieData.map(s => (
                  <Cell key={s.n} fill={s.color}/>
                ))}
              </Pie>
              <Tooltip
                formatter={(value, name) => [
                  `${value} (${tot ? ((value / tot) * 100).toFixed(1) : 0}%)`,
                  name,
                ]}
                contentStyle={{
                  background:C.card, border:`1px solid ${C.border}`, borderRadius:8,
                  fontSize:11, color:C.text,
                }}
                itemStyle={{color:C.text}}
                labelStyle={{color:C.muted}}
              />
            </PieChart>
          </ResponsiveContainer>
        </div>
        <div style={{display:'flex',flexDirection:'column',gap:6,minWidth:140,flex:1}}>
          {counts.map(s => (
            <div key={s.n} style={{display:'flex',alignItems:'center',gap:6,fontSize:10}}>
              <span style={{width:8,height:8,borderRadius:2,background:s.color,flexShrink:0}}/>
              <span style={{color:C.muted,fontWeight:600,flex:1}}>{s.label}</span>
              <span style={{color:C.text,fontWeight:800}}>{s.value}</span>
              <span style={{color:C.muted,minWidth:36,textAlign:'right'}}>
                ({tot ? ((s.value / tot) * 100).toFixed(0) : 0}%)
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

// ── EMA Breadth Table — % of stocks above 9/21/50-day EMA per day,
// plus daily Stage 2 count (going forward only, see backend notes). ──
function EmaBreadthTable({data,isMobile,dragProps,rangeLabel}){
  if(!data||data.length===0) return null
  const pct=(n,total)=>total?Math.round(n/total*100):0
  return(
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:'14px 14px 4px',marginBottom:14}}>
      <div style={{fontWeight:800,fontSize:13,marginBottom:2}}>📅 Stocks Above EMA{rangeLabel?` — ${rangeLabel}`:''}</div>
      <div style={{fontSize:10,color:C.muted,marginBottom:10}}>
        % of tracked stocks trading above their 9/21/50-day average, plus daily Stage 2 count
        {data.some(d=>d.stage2_count==null) && ' (Stage 2 only available from when this was added — no history before that)'}
      </div>
      <div ref={dragProps?.ref} {...(dragProps?.handlers||{})}
        style={{overflowX:'auto',overflowY:'auto',maxHeight:420,...(dragProps?.style||{})}}>
        <table style={{width:'100%',borderCollapse:'collapse',minWidth:520}}>
          <thead>
            <tr style={{borderBottom:`1px solid ${C.border}`,position:'sticky',top:0,background:C.card}}>
              {['Date','Above EMA9','Above EMA21','Above EMA50','Stage 2'].map(h=>(
                <th key={h} style={{textAlign:h==='Date'?'left':'right',padding:'6px 10px',
                  fontSize:10,fontWeight:700,color:C.muted,textTransform:'uppercase',letterSpacing:'0.04em'}}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {[...data].reverse().map(d=>(
              <tr key={d.date} style={{borderBottom:`1px solid ${C.divider}`}}>
                <td style={{padding:'7px 10px',fontSize:11.5,fontWeight:600,color:C.text}}>{d.date}</td>
                <td style={{padding:'7px 10px',fontSize:11.5,textAlign:'right',color:pct(d.above_ema9,d.total)>=50?C.green:C.red}}>
                  {pct(d.above_ema9,d.total)}% <span style={{color:C.muted,fontSize:10}}>({d.above_ema9})</span>
                </td>
                <td style={{padding:'7px 10px',fontSize:11.5,textAlign:'right',color:pct(d.above_ema21,d.total)>=50?C.green:C.red}}>
                  {pct(d.above_ema21,d.total)}% <span style={{color:C.muted,fontSize:10}}>({d.above_ema21})</span>
                </td>
                <td style={{padding:'7px 10px',fontSize:11.5,textAlign:'right',color:pct(d.above_ema50,d.total)>=50?C.green:C.red}}>
                  {pct(d.above_ema50,d.total)}% <span style={{color:C.muted,fontSize:10}}>({d.above_ema50})</span>
                </td>
                <td style={{padding:'7px 10px',fontSize:11.5,textAlign:'right',color:C.text}}>
                  {d.stage2_count!=null ? <>{pct(d.stage2_count,d.total)}% <span style={{color:C.muted,fontSize:10}}>({d.stage2_count})</span></> : '—'}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

// Tabbed detail under the chart: About, Fundamentals ratios, Results / filings.
const STOCK_DETAIL_TABS = [
  {key: 'about', label: 'About Company'},
  {key: 'fundamentals', label: 'Fundamentals'},
  {key: 'results', label: 'Results'},
  {key: 'resultsSummary', label: 'Results Summary'},
  {key: 'concall', label: 'Concall Report'},
  {key: 'ppt', label: 'PPT'},
]

function isBankLikeStock(x){
  const t = `${x?.sector||''} ${x?.industry||''}`.toLowerCase()
  return /bank|nbfc|housing finance|finance - housing|finance - nbfc|financing -/.test(t)
}

function fundLabelColor(label){
  if(label==='Excellent') return C.green
  if(label==='Good') return '#7dd3a8'
  if(label==='Fair') return C.yellow
  if(label==='Poor') return C.red
  return C.muted
}

/** Mirror of live_scan.compute_fundamental_score — client fallback when
 *  stocks.fundamental_score is null but ratios are already on the row. */
function computeFundamentalScore(row){
  if(!row) return null
  const n = (a,b)=>{ const v=row[a]??row[b]; return typeof v==='number'&&!Number.isNaN(v)?v:null }
  const t = (a,b)=>{ const v=row[a]??row[b]; return typeof v==='string'?v:null }
  let score = 0
  const roe = n('roe','roe')
  if(roe!=null){
    if(roe>=20) score += 20
    else if(roe>=15) score += 15
    else if(roe>=10) score += 8
    else if(roe<0) score -= 15
  }
  const epsQoq = n('epsQoq','eps_qoq'), epsYoy = n('epsYoy','eps_yoy')
  if(epsQoq!=null && epsYoy!=null){
    if(epsQoq>0 && epsYoy>0) score += 18
    else if(epsYoy>0) score += 8
    else if(epsYoy<-10) score -= 12
  }
  const salesQoq = n('salesQoq','sales_qoq'), salesYoy = n('salesYoy','sales_yoy')
  if(salesQoq!=null && salesYoy!=null){
    if(salesQoq>0 && salesYoy>0) score += 14
    else if(salesYoy>0) score += 6
    else if(salesYoy<-10) score -= 10
  }
  const debtEq = n('debtEq','debt_eq')
  if(debtEq!=null){
    if(debtEq<0.3) score += 12
    else if(debtEq<1) score += 6
    else if(debtEq>2) score -= 15
    else if(debtEq>1.5) score -= 8
  }
  const opmTrend = t('opmTrend','opm_trend')
  if(opmTrend==='increasing') score += 10
  else if(opmTrend==='decreasing') score -= 8
  const promoterTrend = t('promoterTrend','promoter_trend')
  if(promoterTrend==='increasing') score += 8
  else if(promoterTrend==='decreasing') score -= 12
  if(t('fiiTrend','fii_trend')==='increasing' || t('diiTrend','dii_trend')==='increasing') score += 6
  const peg = n('pegRatio','peg_ratio')
  if(peg!=null){
    if(peg>0 && peg<=1) score += 8
    else if(peg>3) score -= 6
  }
  const streak = n('epsGrowthStreak','eps_growth_streak')
  if(streak!=null && streak>=3) score += 4
  // Need at least one real input — don't invent Fair·50 from an empty row
  const hasSignal = [roe,epsYoy,salesYoy,debtEq,opmTrend,promoterTrend,peg].some(v=>v!=null)
  if(!hasSignal) return null
  return Math.round(Math.max(0, Math.min(100, score + 50)) * 10) / 10
}

function fundamentalScoreLabel(score){
  if(score==null) return null
  if(score>=75) return 'Excellent'
  if(score>=58) return 'Good'
  if(score>=40) return 'Fair'
  return 'Poor'
}

/** Prefer stored scan score; else compute instantly from ratios on hand. */
function ensureFundamentalQuality(row){
  if(!row) return {score:null, label:null}
  let score = row.fundamentalScore ?? row.fundamental_score
  if(typeof score!=='number' || Number.isNaN(score)) score = computeFundamentalScore(row)
  let label = row.fundamentalLabel || row.fundamental_label || null
  if(score!=null && !label) label = fundamentalScoreLabel(score)
  if(score==null) label = null
  return {score, label}
}

