function flagToneColor(tone){
  if(tone==='green') return C.green
  if(tone==='red') return C.red
  return C.yellow
}

function FlagsList({flags, compact}){
  const list = Array.isArray(flags) ? flags : []
  if(!list.length) return null
  return (
    <div style={{display:'flex',flexDirection:'column',gap:compact?6:8}}>
      {list.map((f,i)=>{
        const tone = flagToneColor(f.tone)
        const mark = f.tone==='green'?'✓':f.tone==='red'?'⚑':'•'
        return (
          <div key={i} style={{
            display:'flex',gap:8,alignItems:'flex-start',
            padding:compact?'7px 9px':'8px 10px',borderRadius:8,
            background:tone+'12',border:`1px solid ${tone}44`,
          }}>
            <span style={{
              fontSize:10,fontWeight:900,color:tone,flexShrink:0,marginTop:1,
              width:16,textAlign:'center',
            }}>{mark}</span>
            <div style={{minWidth:0}}>
              <div style={{fontSize:12,fontWeight:800,color:C.text}}>{f.title}</div>
              {f.detail&&(
                <div style={{fontSize:11.5,lineHeight:1.45,color:C.muted,marginTop:2}}>{f.detail}</div>
              )}
            </div>
          </div>
        )
      })}
    </div>
  )
}

function MgmtFlagsCard({symbol, compact}){
  const [info, setInfo] = useState(undefined)
  useEffect(()=>{
    let cancelled=false
    setInfo(undefined)
    if(!symbol){ setInfo(null); return }
    fetchMgmtFlags(symbol).then(row=>{ if(!cancelled) setInfo(row) })
    return()=>{cancelled=true}
  },[symbol])
  if(!info) return null
  const verdict = (info.verdict||'unknown').toLowerCase()
  const vColor = verdict==='trustworthy'?C.green:verdict==='caution'?C.red:verdict==='mixed'?C.yellow:C.muted
  const dateLabel = info.at
    ? new Date(info.at).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})
    : null
  return (
    <div style={{
      marginBottom: compact?10:12,
      background:C.card,border:`1px solid ${vColor}44`,borderRadius:10,
      padding:compact?'9px 11px':'11px 13px',
    }}>
      <div style={{display:'flex',justifyContent:'space-between',gap:8,alignItems:'flex-start',marginBottom:8,flexWrap:'wrap'}}>
    <div>
          <div style={{fontSize:11,fontWeight:900,color:vColor,textTransform:'uppercase',letterSpacing:'0.04em'}}>
            Flags · Management diligence
          </div>
          <div style={{fontSize:9,color:C.muted,marginTop:1}}>
            Promise vs execution · from PPT/Concall on file{dateLabel?` · ${dateLabel}`:''}
          </div>
        </div>
        <div style={{display:'flex',alignItems:'center',gap:6,flexShrink:0}}>
          <SectionFeedback symbol={symbol} contentType="flags" sectionKey="mgmt_flags"
            sectionLabel="Management flags"/>
          <span style={{
            fontSize:9,fontWeight:800,color:vColor,background:vColor+'22',
            border:`1px solid ${vColor}55`,borderRadius:999,padding:'2px 8px',textTransform:'uppercase',
          }}>{verdict}</span>
        </div>
      </div>
      {info.summary&&(
        <div style={{fontSize:12,lineHeight:1.5,color:C.text,marginBottom:info.flags?.length?8:0}}>
          {info.summary}
        </div>
      )}
      <FlagsList flags={info.flags} compact={compact}/>
    </div>
  )
}

const ASK_AI_SUGGESTIONS = [
  'Is management trustworthy or not?',
  'Any red flags in recent filings or concalls?',
  'Do they deliver on growth / capex promises?',
]

function AskAiAgent({symbol, isMobile}){
  // Inline control in the detail tab row — never a floating FAB over tabs.
  const [open, setOpen] = useState(false)
  const [q, setQ] = useState('')
  const [busy, setBusy] = useState(false)
  const [active, setActive] = useState(null)
  const [recent, setRecent] = useState([])
  const [err, setErr] = useState(null)
  const [askMode, setAskMode] = useState('filings') // 'filings' | 'web'

  useEffect(()=>{
    let cancelled=false
    setActive(null); setQ(''); setErr(null); setOpen(false)
    if(!symbol){ setRecent([]); return }
    fetchRecentStockAiAsks(symbol).then(rows=>{ if(!cancelled) setRecent(rows||[]) })
    return()=>{cancelled=true}
  },[symbol])

  useEffect(()=>{
    if(!open || !active?.id || active.status!=='pending') return
    let cancelled=false
    const tick = async ()=>{
      const row = await fetchStockAiAsk(active.id)
      if(cancelled || !row) return
      setActive(row)
      if(row.status==='done' || row.status==='error'){
        setBusy(false)
        if(row.status==='done'){
          fetchRecentStockAiAsks(symbol).then(rows=>setRecent(rows||[]))
        }
      }
    }
    const id = setInterval(tick, 1000)
    tick()
    return()=>{cancelled=true; clearInterval(id)}
  },[open, active?.id, active?.status, symbol])

  if(!symbol) return null

  const submit = async (text)=>{
    const question = (text||q||'').trim()
    if(busy || question.length<8) return
    setErr(null)
    setBusy(true)
    setActive({status:'pending', question, ask_mode: askMode})
    const res = await submitStockAiAsk(symbol, question, askMode)
    if(res.error){
      setErr(res.error)
      setBusy(false)
      setActive(null)
      return
    }
    setQ('')
    setActive(res.ask)
  }

  return (
    <>
      {!open&&(
        <button type="button" onClick={()=>setOpen(true)} title="Ask AI agent"
          style={{
            flexShrink:0,
            display:'inline-flex',alignItems:'center',gap:isMobile?4:6,
            padding:isMobile?'5px 10px':'6px 12px',borderRadius:999,cursor:'pointer',
            border:`1px solid ${C.accent}66`,
            background:`linear-gradient(135deg, ${C.accent}, ${C.teal||C.accent})`,
            color:'#0a0e14',fontSize:isMobile?11:12,fontWeight:900,
            whiteSpace:'nowrap',
          }}>
          <span style={{fontSize:isMobile?12:13}}>✦</span>{isMobile?'Ask':'Ask AI'}
        </button>
      )}

      {open&&(
        <div style={{
          position:'fixed',inset:0,zIndex:2200,
          display:'flex',alignItems:isMobile?'flex-end':'center',justifyContent:'center',
          padding:isMobile
            ? '0 0 env(safe-area-inset-bottom, 0px)'
            : 'max(16px, env(safe-area-inset-top, 0px)) 16px max(16px, env(safe-area-inset-bottom, 0px))',
          background:'rgba(0,0,0,0.55)',
        }}
          onClick={()=>!busy&&setOpen(false)}>
          <div onClick={e=>e.stopPropagation()}
            style={{
              width:isMobile?'100%':'min(420px, 100%)',
              maxWidth:'100%',
              height:isMobile?'min(82dvh, 82vh)':'min(560px, calc(100dvh - 32px))',
              maxHeight:isMobile?'min(82dvh, 82vh)':'min(560px, calc(100dvh - 32px))',
              display:'flex',flexDirection:'column',
              background:C.card,
              border:isMobile?`1px solid ${C.border}`:`1px solid ${C.accent}44`,
              borderRadius:isMobile?'16px 16px 0 0':16,
              boxShadow:'0 20px 60px rgba(0,0,0,0.55)',
              overflow:'hidden',
            }}>
            <div style={{
              padding:'12px 14px',flexShrink:0,
              background:`linear-gradient(135deg, ${C.accent}22, ${C.card})`,
              borderBottom:`1px solid ${C.border}`,
              display:'flex',alignItems:'center',justifyContent:'space-between',gap:10,
            }}>
              <div style={{minWidth:0}}>
                <div style={{fontSize:14,fontWeight:900,color:C.text,display:'flex',alignItems:'center',gap:7}}>
                  <span style={{
                    width:26,height:26,borderRadius:8,display:'inline-flex',alignItems:'center',justifyContent:'center',
                    background:C.accent,color:'#0a0e14',fontSize:13,fontWeight:900,
                  }}>✦</span>
                  Ask AI agent
                </div>
                <div style={{fontSize:10,color:C.muted,marginTop:2}}>
                  {symbol} · Filings or Web · not investment advice
                </div>
              </div>
              <button type="button" onClick={()=>setOpen(false)}
                style={{background:'transparent',border:`1px solid ${C.border}`,color:C.muted,
                  width:30,height:30,borderRadius:8,cursor:'pointer',fontSize:16,lineHeight:1}}>×</button>
            </div>

            <div style={{flex:1,overflowY:'auto',padding:'12px 14px'}}>
              <div style={{display:'flex',gap:6,marginBottom:10,flexWrap:'wrap'}}>
                {[
                  {id:'filings', label:'Filings only', hint:'PPT / Concall on file'},
                  {id:'web', label:'Web research', hint:'Google Search + filings'},
                ].map(m=>{
                  const on = askMode===m.id
                  return (
                    <button key={m.id} type="button" disabled={busy} onClick={()=>setAskMode(m.id)}
                      title={m.hint}
                      style={{
                        padding:'6px 12px',borderRadius:999,cursor:busy?'default':'pointer',
                        border:`1px solid ${on?C.accent:C.border}`,
                        background:on?C.accent+'22':'transparent',
                        color:on?C.accent:C.muted,fontSize:11,fontWeight:800,
                      }}>
                      {m.label}
                    </button>
                  )
                })}
              </div>

              <MgmtFlagsCard symbol={symbol} compact/>

              <div style={{display:'flex',flexWrap:'wrap',gap:6,marginBottom:10}}>
                {ASK_AI_SUGGESTIONS.map(s=>(
                  <button key={s} type="button" disabled={busy} onClick={()=>submit(s)}
                    style={{
                      fontSize:10,fontWeight:700,cursor:busy?'default':'pointer',
                      padding:'5px 9px',borderRadius:999,
                      border:`1px solid ${C.border}`,background:C.bg,color:C.muted,
                    }}>
                    {s}
                  </button>
                ))}
              </div>

              {err&&<div style={{marginBottom:8,fontSize:11,color:C.red}}>{err}</div>}

              {active&&(
                <div style={{marginBottom:12,padding:'10px 12px',borderRadius:10,background:C.bg,border:`1px solid ${C.border}`}}>
                  <div style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:'uppercase',marginBottom:6,display:'flex',gap:8,alignItems:'center',flexWrap:'wrap'}}>
                    <span>
                      {active.status==='pending'?'Researching…'
                        : active.status==='error'?'Could not answer'
                          : 'Answer'}
                    </span>
                    {(active.ask_mode||askMode)&&(
                      <span style={{
                        fontSize:9,fontWeight:700,color:C.accent,background:C.accent+'18',
                        border:`1px solid ${C.accent}44`,borderRadius:999,padding:'1px 7px',
                      }}>
                        {(active.ask_mode||askMode)==='web'?'Web research':'Filings only'}
                      </span>
                    )}
                  </div>
                  <div style={{fontSize:12,fontWeight:700,color:C.text,marginBottom:8}}>{active.question}</div>
                  {active.status==='pending'&&(
                    <div style={{fontSize:11,color:C.muted}}>
                      {(active.ask_mode||askMode)==='web'
                        ? 'Working… usually 10–40 seconds (falls back fast if web is slow).'
                        : 'Working… usually 5–20 seconds.'}
                    </div>
                  )}
                  {active.status==='error'&&(
                    <div style={{fontSize:12,color:C.red}}>{active.error||'Try again in a minute.'}</div>
                  )}
                  {active.status==='done'&&(
                    <>
                      {active.verdict&&(
                        <div style={{marginBottom:8}}>
                          <span style={{
                            fontSize:9,fontWeight:800,color:C.accent,background:C.accent+'18',
                            border:`1px solid ${C.accent}44`,borderRadius:999,padding:'2px 8px',textTransform:'uppercase',
                          }}>{active.verdict}</span>
                        </div>
                      )}
                      <div style={{fontSize:12.5,lineHeight:1.55,color:C.text,whiteSpace:'pre-wrap'}}>{active.answer}</div>
                      <div style={{marginTop:10}}>
                        <div style={{fontSize:9,fontWeight:800,color:C.muted,textTransform:'uppercase',marginBottom:6}}>Flags</div>
                        <FlagsList flags={active.flags}/>
                      </div>
                      {Array.isArray(active.sources)&&active.sources.some(s=>s?.url)&&(
                        <div style={{marginTop:10}}>
                          <div style={{fontSize:9,fontWeight:800,color:C.muted,textTransform:'uppercase',marginBottom:4}}>Sources</div>
                          {active.sources.filter(s=>s?.url).slice(0,4).map((s,i)=>(
                            <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                              style={{display:'block',fontSize:11,color:C.accent,textDecoration:'none',
                                overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
                              {s.title||s.url}
                            </a>
                          ))}
                        </div>
                      )}
                    </>
                  )}
                </div>
              )}

              {recent.length>0&&!(active&&(active.status==='done'||active.status==='pending'))&&(
                <div style={{marginBottom:8}}>
                  <div style={{fontSize:9,fontWeight:800,color:C.muted,textTransform:'uppercase',marginBottom:6}}>Recent asks</div>
                  {recent.slice(0,3).map(r=>(
                    <button key={r.id} type="button" onClick={()=>setActive(r)}
                      style={{
                        display:'block',width:'100%',textAlign:'left',marginBottom:6,
                        padding:'8px 10px',borderRadius:8,cursor:'pointer',
                        border:`1px solid ${C.border}`,background:C.bg,color:C.text,fontSize:11,
                      }}>
                      {r.ask_mode==='web'?'🌐 ':''}{r.question}
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div style={{padding:'10px 12px',borderTop:`1px solid ${C.border}`,flexShrink:0,background:C.card}}>
              <div style={{display:'flex',gap:8,alignItems:'stretch'}}>
                <input
                  value={q}
                  onChange={e=>setQ(e.target.value)}
                  onKeyDown={e=>{ if(e.key==='Enter') submit() }}
                  placeholder={`Ask about ${symbol}…`}
                  disabled={busy}
                  maxLength={400}
                  autoFocus
                  style={{
                    flex:1,padding:'10px 12px',borderRadius:10,border:`1px solid ${C.border}`,
                    background:C.bg,color:C.text,fontSize:12,outline:'none',
                  }}
                />
                <button type="button" onClick={()=>submit()} disabled={busy || q.trim().length<8}
                  style={{
                    padding:'10px 14px',borderRadius:10,fontSize:12,fontWeight:900,cursor:busy?'default':'pointer',
                    border:'none',background:C.accent,color:'#0a0e14',
                    opacity:(busy || q.trim().length<8)?0.5:1,
                  }}>
                  {busy?'…':'Ask'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

function FundamentalsPanel({symbol, stocks}){
  const scan = stocks?.find(x=>x.sym===symbol) || null
  const [fundRow, setFundRow] = useState(undefined) // undefined=loading
  useEffect(()=>{
    let cancelled=false
    setFundRow(undefined)
    if(!symbol){ setFundRow(null); return }
    fetchStockFundamentals(symbol).then(row=>{ if(!cancelled) setFundRow(row) })
    return()=>{cancelled=true}
  },[symbol])

  if(fundRow===undefined && !scan){
    return <div style={{padding:'12px',fontSize:11,color:C.muted,textAlign:'center',
      background:C.card,border:`1px solid ${C.border}`,borderRadius:10}}>
      Loading fundamentals…
    </div>
  }

  const s = mergeFundamentalsOntoStock(scan, fundRow || null)
  const hasAny = fundRow || (scan && (scan.pe!=null || scan.roe!=null || scan.marketCap!=null
    || scan.fundamentalLabel || scan.cfo!=null || scan.pb!=null))
  if(!hasAny && fundRow===null){
    return (
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:'14px 16px'}}>
        <div style={{fontSize:13,fontWeight:800,color:C.text,marginBottom:6}}>Fundamentals</div>
        <div style={{fontSize:12,color:C.muted,lineHeight:1.55}}>
          Ratios for {symbol||'this stock'} are still being scraped / AI-filled.
          They appear here once the fundamentals worker finishes a cycle.
        </div>
      </div>
    )
  }

  const allCards = buildFundamentalMetricCards(s)
  const aiKeys = Array.isArray(fundRow?.ai_key_metrics) ? fundRow.ai_key_metrics : []
  const importantKeys = aiKeys
    .map(k=>FUND_DB_KEY_TO_CARD[k] || FUND_DB_KEY_TO_CARD[String(k).toLowerCase()])
    .filter(Boolean)
  const defaultImportant = isBankLikeStock(s)
    ? ['pe','pb','roe','nim','nnpa','car','casa','cfoPat']
    : ['pe','pb','roe','roce','pegRatio','cfo','fcf','cfoPat','epsYoy','debtEq']
  const focusKeys = (importantKeys.length >= 3 ? importantKeys : defaultImportant)
  const byKey = Object.fromEntries(allCards.map(c=>[c.key,c]))
  const importantCards = [...new Set(focusKeys)].map(k=>byKey[k]).filter(Boolean)
  const importantSet = new Set(importantCards.map(c=>c.key))
  const restCards = allCards.filter(c=>!importantSet.has(c.key))
  const highlights = normalizeBullets(fundRow?.ai_highlights)
  const {score: fundScore, label} = ensureFundamentalQuality(s)
  const labelCol = fundLabelColor(label)
  const updated = fundRow?.ai_highlights_at || fundRow?.fetched_at
  const updatedLabel = updated
    ? new Date(updated).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})
    : null

  return (
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,overflow:'hidden'}}>
      <div style={{height:3,background:`linear-gradient(90deg, ${C.teal}, ${C.accent})`}}/>
      <div style={{padding:'12px 14px'}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:10,marginBottom:10}}>
          <div>
            <div style={{fontSize:13,fontWeight:900,color:C.text}}>Fundamentals · {symbol}</div>
            <div style={{fontSize:10,color:C.muted,marginTop:2}}>
              Important ratios · AI ranks what matters for this business · not investment advice
            </div>
          </div>
          <div style={{display:'flex',flexDirection:'column',alignItems:'flex-end',gap:4,flexShrink:0}}>
            {label&&(
              <span title="Overall fundamental quality (ROE, growth, debt, margins, ownership) — not the same as Excellent/Good Result (latest quarter only)."
                style={{fontSize:10,fontWeight:800,color:labelCol,background:labelCol+'22',
                  border:`1px solid ${labelCol}55`,borderRadius:999,padding:'3px 9px',cursor:'help'}}>
                {label}{fundScore!=null?` · ${Math.round(fundScore)}`:''}
              </span>
            )}
            {updatedLabel&&(
              <span style={{fontSize:9,fontWeight:700,color:C.muted}}>{updatedLabel}</span>
            )}
          </div>
        </div>

        {highlights.length>0?(
          <div style={{marginBottom:14,padding:'10px 12px',borderRadius:10,
            background:C.teal+'12',border:`1px solid ${C.teal}33`}}>
            <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8,marginBottom:6}}>
              <div style={{fontSize:10,fontWeight:800,color:C.teal,textTransform:'uppercase',
                letterSpacing:'0.04em'}}>AI takeaways</div>
              <SectionFeedback symbol={symbol} contentType="fundamentals" sectionKey="ai_highlights"
                sectionLabel="AI takeaways"/>
            </div>
            <ul style={{margin:0,paddingLeft:16,fontSize:12.5,lineHeight:1.5,color:C.text}}>
              {highlights.map((h,i)=><li key={i} style={{marginBottom:4}}>{h}</li>)}
            </ul>
          </div>
       ):(
          <div style={{marginBottom:12,fontSize:11,color:C.muted,lineHeight:1.45}}>
            AI takeaways generate in the background once enough ratios are on file.
          </div>
        )}

        <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8,marginBottom:8}}>
          <div style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:'uppercase',
            letterSpacing:'0.04em'}}>
            {aiKeys.length>=3?'AI-picked important metrics':'Important metrics'}
          </div>
          <SectionFeedback symbol={symbol} contentType="fundamentals" sectionKey="important_metrics"
            sectionLabel="Important metrics"/>
        </div>
        <MetricCardsGrid cards={importantCards}/>

        {restCards.length>0&&(
          <div style={{marginTop:14}}>
            <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8,marginBottom:8}}>
              <div style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:'uppercase',
                letterSpacing:'0.04em'}}>All metrics</div>
              <SectionFeedback symbol={symbol} contentType="fundamentals" sectionKey="all_metrics"
                sectionLabel="All metrics"/>
            </div>
            <MetricCardsGrid cards={restCards}/>
          </div>
        )}
      </div>
    </div>
  )
}

function CorporateNewsSection({symbol, news, loading}){
  const ratingColor = r => {
    if(!r) return C.muted
    const t = String(r).toLowerCase()
    if(t.includes('positive')||t.includes('bull')) return C.green
    if(t.includes('negative')||t.includes('bear')) return C.red
    return C.yellow
  }
  return (
    <div style={{
      background:`linear-gradient(135deg, ${C.accent}1a 0%, ${C.accent}05 100%)`,
      border:`1px solid ${C.accent}40`,borderRadius:10,padding:'10px 12px',marginTop:12,
      boxShadow:`0 1px 3px ${C.accent}15`,
    }}>
      <div style={{display:'flex',alignItems:'center',gap:7,marginBottom:8}}>
        <div style={{
          width:22,height:22,borderRadius:'50%',flexShrink:0,
          background:`linear-gradient(135deg, ${C.accent}, ${C.accent}bb)`,
          display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,
          boxShadow:`0 1px 4px ${C.accent}66`,
        }}>📰</div>
        <div style={{fontSize:11,fontWeight:800,color:C.text,letterSpacing:'0.02em',
          textTransform:'uppercase',flex:1}}>Corporate news</div>
        <span style={{fontSize:9,color:C.muted}}>NSE filings</span>
      </div>
      {loading?(
        <div style={{fontSize:11,color:C.muted}}>Loading filings…</div>
      ):!news?.length?(
        <div style={{fontSize:11,color:C.muted,lineHeight:1.5}}>
          No recent NSE corporate filings for {symbol} in our feed yet.
        </div>
      ):(
        <div style={{display:'flex',flexDirection:'column',gap:8}}>
          {news.map((a,i)=>{
            const when = a.announced_at
              ? new Date(a.announced_at).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})
              : null
            const body = a.ai_summary || a.subject || a.category || 'Filing'
            const title = a.subject || a.category || 'Corporate filing'
            return (
              <div key={`${a.announced_at||i}-${a.attachment_url||i}`}
                style={{background:C.bg,border:`1px solid ${C.border}`,borderRadius:8,padding:'8px 10px'}}>
                <div style={{display:'flex',alignItems:'baseline',gap:8,flexWrap:'wrap',marginBottom:3}}>
                  {when&&<span style={{fontSize:10,fontWeight:700,color:C.muted}}>{when}</span>}
                  {a.category&&(
                    <span style={{fontSize:9,fontWeight:700,color:C.accent,background:C.accent+'18',
                      borderRadius:999,padding:'1px 7px'}}>{a.category}</span>
                  )}
                  {a.ai_rating&&(
                    <span style={{fontSize:9,fontWeight:800,color:ratingColor(a.ai_rating)}}>
                      {a.ai_rating}
                    </span>
                  )}
                </div>
                <div style={{fontSize:12,fontWeight:700,color:C.text,lineHeight:1.35,marginBottom:a.ai_summary?4:0}}>
                  {a.attachment_url?(
                    <a href={a.attachment_url} target="_blank" rel="noopener noreferrer"
                      style={{color:C.text,textDecoration:'none'}}>
                      {title} <span style={{color:C.accent,fontSize:10}}>↗</span>
                    </a>
                  ):title}
                </div>
                {a.ai_summary&&(
                  <div style={{fontSize:11,color:C.muted,lineHeight:1.45}}>{body}</div>
                )}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

function AboutCompanyPanel({symbol, stocks}){
  const s = stocks?.find(x=>x.sym===symbol) || null
  const [about, setAbout] = useState(undefined) // undefined=loading
  const [news, setNews] = useState(undefined) // undefined=loading
  const [imgBroken, setImgBroken] = useState(false)
  useEffect(()=>{
    let cancelled=false
    setAbout(undefined)
    setNews(undefined)
    setImgBroken(false)
    if(!symbol){ setAbout(null); setNews([]); return }
    fetchCompanyAbout(symbol).then(row=>{ if(!cancelled) setAbout(row) })
    fetchSymbolCorporateNews(symbol, 12).then(rows=>{ if(!cancelled) setNews(rows||[]) })
    return()=>{cancelled=true}
  },[symbol])

  if(about===undefined){
    return <div style={{padding:'12px',fontSize:11,color:C.muted,textAlign:'center',
      background:C.card,border:`1px solid ${C.border}`,borderRadius:10}}>
      Loading company brief…
    </div>
  }
  if(!about){
    return (
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:'14px 16px'}}>
        <div style={{fontSize:13,fontWeight:800,color:C.text,marginBottom:6}}>About Company</div>
        <div style={{fontSize:12,color:C.muted,lineHeight:1.55}}>
          AI company brief for {symbol||'this stock'} is not ready yet. The worker fills About
          from filings / known company facts (large caps and your priority symbols first).
          Check back after the next few cycles.
        </div>
        {s?.industry||s?.sector?(
          <div style={{marginTop:10,fontSize:11,color:C.text}}>
            Sector: <span style={{color:C.muted}}>{[s.industry,s.sector].filter(Boolean).join(' · ')}</span>
          </div>
        ):null}
        <CorporateNewsSection symbol={symbol} news={news||[]} loading={news===undefined}/>
      </div>
    )
  }

  const customers = normalizeBullets(about.customers)
  const segments = normalizeBullets(about.segments)
  const innovation = normalizeBullets(about.innovation)
  const srcDate = about.updated_at || about.source_announced_at
    ? new Date(about.updated_at || about.source_announced_at).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})
    : null
  const showImg = about.image_url && !imgBroken
  const monogram = (symbol||'?').slice(0,1).toUpperCase()

  return (
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,overflow:'hidden'}}>
      <div style={{height:3,background:`linear-gradient(90deg, ${C.accent}, ${C.teal})`}}/>
      <div style={{padding:'12px 14px'}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:10,marginBottom:10}}>
          <div style={{display:'flex',alignItems:'center',gap:10,minWidth:0}}>
            <div style={{width:44,height:44,borderRadius:10,flexShrink:0,overflow:'hidden',
              background:`linear-gradient(135deg,${C.accent}33,${C.purple}33)`,
              border:`1px solid ${C.border}`,display:'flex',alignItems:'center',justifyContent:'center'}}>
              {showImg?(
                <img src={about.image_url} alt={`${symbol} logo`}
                  onError={()=>setImgBroken(true)}
                  style={{width:'100%',height:'100%',objectFit:'contain',background:'#fff',padding:4}}/>
              ):(
                <span style={{fontWeight:900,fontSize:18,color:C.accent}}>{monogram}</span>
              )}
            </div>
            <div style={{minWidth:0}}>
              <div style={{fontSize:13,fontWeight:900,color:C.text}}>About {symbol}</div>
              <div style={{fontSize:10,color:C.muted,marginTop:2}}>
                {Array.isArray(about.sources)&&about.sources.some(s=>s?.url)
                  ? 'AI web research + filings · not investment advice'
                  : 'AI company brief from filings · not investment advice'}
              </div>
              {about.website&&(
                <a href={`https://${about.website}`} target="_blank" rel="noopener noreferrer"
                  style={{fontSize:10,color:C.accent,textDecoration:'none'}}>
                  {about.website} ↗
                </a>
              )}
            </div>
          </div>
          {srcDate&&(
            <span style={{fontSize:9,fontWeight:700,color:C.accent,background:C.accent+'18',
              border:`1px solid ${C.accent}44`,borderRadius:999,padding:'3px 8px',flexShrink:0}}>
              Updated {srcDate}
            </span>
          )}
        </div>

        {about.overall_brief&&(
          <div style={{marginBottom:12}}>
            <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8,marginBottom:4}}>
              <div style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:'uppercase',
                letterSpacing:'0.04em'}}>Overview</div>
              <SectionFeedback symbol={symbol} contentType="about" sectionKey="overall_brief"
                sectionLabel="Overview"/>
            </div>
            <div style={{fontSize:12.5,lineHeight:1.55,color:C.text,
              borderLeft:`3px solid ${C.accent}`,paddingLeft:10}}>
              {about.overall_brief}
            </div>
          </div>
        )}
        {about.what_they_do&&(
          <div style={{marginBottom:12}}>
            <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8,marginBottom:4}}>
              <div style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:'uppercase',
                letterSpacing:'0.04em'}}>What they do</div>
              <SectionFeedback symbol={symbol} contentType="about" sectionKey="what_they_do"
                sectionLabel="What they do"/>
            </div>
            <div style={{fontSize:12.5,lineHeight:1.5,color:C.text}}>{about.what_they_do}</div>
          </div>
        )}
        {customers.length>0&&(
          <BulletSection icon="👥" label="Customers & markets" color={C.blue} bullets={customers}
            feedback={{symbol, contentType:'about', sectionKey:'customers'}}/>
        )}
        {segments.length>0&&(
          <BulletSection icon="🧩" label="Business segments" color={C.teal} bullets={segments}
            feedback={{symbol, contentType:'about', sectionKey:'segments'}}/>
        )}
        {innovation.length>0&&(
          <BulletSection icon="🚀" label="Innovation & strategy" color={C.lime} bullets={innovation}
            feedback={{symbol, contentType:'about', sectionKey:'innovation'}}/>
        )}
        <CorporateNewsSection symbol={symbol} news={news||[]} loading={news===undefined}/>
        {Array.isArray(about.sources)&&about.sources.some(s=>s?.url)&&(
          <div style={{marginTop:12,paddingTop:10,borderTop:`1px solid ${C.border}`}}>
            <div style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:'uppercase',
              letterSpacing:'0.04em',marginBottom:6}}>Sources</div>
            <div style={{display:'flex',flexDirection:'column',gap:4}}>
              {about.sources.filter(s=>s?.url).slice(0,6).map((s,i)=>(
                <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                  style={{fontSize:11,color:C.accent,textDecoration:'none',
                    overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
                  {s.title||s.url}
                </a>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

function StockDetailTabs({sym, stocks, onSelectSymbol, tab, setTab, scrollable, isMobile}){
  // Tab can be controlled by ChartPanel (e.g. peer ranking opens Results).
  const [innerTab, setInnerTab] = useState('about')
  const activeTab = tab ?? innerTab
  const changeTab = setTab ?? setInnerTab
  // Tab flags so users can see Concall/PPT history exists without opening
  // each tab — count + latest filing date. About uses company_abouts;
  // Fundamentals uses stock_fundamentals AI takeaways / ratio coverage.
  const [flags, setFlags] = useState({
    concall: undefined, ppt: undefined, about: undefined,
    fundamentals: undefined, resultsSummary: undefined,
  })
  const scanRow = stocks?.find(x=>x.sym===sym) || null
  const fundQ = ensureFundamentalQuality(scanRow)

  useEffect(() => {
    let cancelled = false
    // Only reset locally when uncontrolled — controlled parent sets tab on navigate.
    if (tab == null) setInnerTab('about')
    setFlags({
      concall: undefined, ppt: undefined, about: undefined,
      fundamentals: undefined, resultsSummary: undefined,
    })
    if (!sym) return
    Promise.all([
      fetchTranscriptSummaries(sym),
      fetchPptSummaries(sym),
      fetchCompanyAbout(sym),
      fetchStockFundamentals(sym),
      fetchConcallSummaries(sym),
    ]).then(([t, p, about, fund, rs]) => {
      if (cancelled) return
      const fundReady = !!(fund && (
        fund.ai_highlights?.length
        || fund.pe != null || fund.roe != null || fund.pb != null || fund.cfo != null
      )) || !!(scanRow && (scanRow.pe!=null || scanRow.roe!=null || fundQ.label))
      setFlags({
        concall: {count: t?.length || 0, latestAt: t?.[0]?.announced_at || null},
        ppt: {count: p?.length || 0, latestAt: p?.[0]?.announced_at || null},
        about: about ? {count: 1, latestAt: about.source_announced_at || about.updated_at || null} : {count: 0, latestAt: null},
        fundamentals: fundReady
          ? {count: 1, latestAt: fund?.ai_highlights_at || fund?.fetched_at || null}
          : {count: 0, latestAt: null},
        resultsSummary: {count: rs?.length || 0, latestAt: rs?.[0]?.announced_at || null},
      })
    })
    return () => { cancelled = true }
  }, [sym]) // eslint-disable-line react-hooks/exhaustive-deps

  const fmtFlagDate = (iso) => {
    if (!iso) return null
    return new Date(iso).toLocaleDateString('en-IN', {day: 'numeric', month: 'short'})
  }

  // Market Cap · Fundamental · Result live on one line above (ChartBelowContent).

  return (
    <div style={scrollable?{display:'flex',flexDirection:'column',flex:1,minHeight:0,height:'100%'}:undefined}>
      <div style={{display:'flex',alignItems:'flex-end',gap:8,marginBottom:10,
        borderBottom:`1px solid ${C.border}`,flexShrink:0,
        position:'sticky', top:0, zIndex:6, background:C.bg, paddingTop:2}}>
        <div style={{display:'flex',gap:4,overflowX:'auto',flex:1,minWidth:0,
          WebkitOverflowScrolling:'touch'}}>
          {STOCK_DETAIL_TABS.map(t=>{
            const flag = t.key==='concall'?flags.concall
              : t.key==='ppt'?flags.ppt
              : t.key==='about'?flags.about
              : t.key==='fundamentals'?flags.fundamentals
              : t.key==='resultsSummary'?flags.resultsSummary
              : null
            const hasContent = flag && flag.count > 0
            const dateHint = hasContent ? fmtFlagDate(flag.latestAt) : null
            return (
              <div key={t.key} onClick={()=>changeTab(t.key)} title={
                t.key==='about'
                  ? (hasContent ? 'AI company brief from web + filings' : 'Brief generates after worker cycles')
                  : t.key==='fundamentals'
                    ? (hasContent ? 'Ratios + AI takeaways' : 'Waiting for fundamentals scrape / AI fill')
                  : t.key==='resultsSummary'
                    ? (hasContent ? 'AI summary of results PDF filing' : 'Waiting for results-PDF AI summary')
                  : hasContent
                    ? `${flag.count} report${flag.count>1?'s':''} on file — open to read history`
                    : (flag && flag.count===0 ? `No ${t.label} yet` : undefined)
              } style={{
            padding:'6px 10px',fontSize:11,fontWeight:700,cursor:'pointer',whiteSpace:'nowrap',
                color:activeTab===t.key?C.accent:C.muted,
                borderBottom:activeTab===t.key?`2px solid ${C.accent}`:'2px solid transparent',
                display:'flex',alignItems:'center',gap:5,
          }}>
            {t.label}
                {hasContent && (()=>{
                  // Date / count only — never a vague "Ready" label.
                  const badgeText = (t.key==='about'||t.key==='fundamentals')
                    ? dateHint
                    : (flag.count>1
                        ? `${flag.count}${dateHint?` · ${dateHint}`:''}`
                        : dateHint)
                  return badgeText ? (
                  <span style={{
                    fontSize:9,fontWeight:800,color:C.green,background:C.green+'22',
                    border:`1px solid ${C.green}55`,borderRadius:999,padding:'1px 6px',
                  }}>
                    {badgeText}
                  </span>
                  ) : null
                })()}
                {flag && flag.count===0 && (t.key==='concall'||t.key==='ppt'||t.key==='about'||t.key==='fundamentals'||t.key==='resultsSummary') && (
                  <span style={{fontSize:9,fontWeight:600,color:C.muted,opacity:0.7}}>—</span>
                )}
          </div>
            )
          })}
      </div>
        <div style={{flexShrink:0,paddingBottom:5,paddingRight:2}}>
          <AskAiAgent symbol={sym} isMobile={!!isMobile}/>
        </div>
      </div>
      <div style={scrollable?{
        flex:1,minHeight:0,overflowY:'auto',overflowX:'hidden',
        paddingRight:4,paddingBottom:16,
        borderTop:`1px solid ${C.border}`,
        marginTop:2,
        scrollbarGutter:'stable',
      }:undefined}>
      {activeTab==='about' && <AboutCompanyPanel symbol={sym} stocks={stocks}/>}
      {activeTab==='fundamentals' && <FundamentalsPanel symbol={sym} stocks={stocks}/>}
      {activeTab==='results' && <ResultsHistoryTable symbol={sym}/>}
      {activeTab==='resultsSummary' && <ResultsFilingSummary symbol={sym}/>}
      {activeTab==='concall' && <TranscriptSummary symbol={sym}/>}
      {activeTab==='ppt' && <PptSummary symbol={sym}/>}
      </div>
    </div>
  )
}

function fmtMarketCapCr(mcap){
  if(mcap==null || !isFinite(mcap)) return null
  if(mcap>=100000) return `₹${(mcap/100000).toFixed(1)}L Cr`
  if(mcap>=1000) return `₹${(mcap/1000).toFixed(1)}K Cr`
  return `₹${mcap.toFixed(0)} Cr`
}

function ChartBelowContent({sym, stocks, sectionOrder, sectionHidden=[], onSectionOrderChange, onSectionHiddenChange, detailTab, setDetailTab, navigateTo, isMobile, readingMode, tableMode, fillParent=false}){
  const [customizeOpen, setCustomizeOpen]=useState(false)
  const hiddenSet=new Set(sectionHidden||[])
  const visibleSections=(sectionOrder||[]).filter(id=>!hiddenSet.has(id))
  const mcapStock=stocks?.find(s=>s.sym===sym)
  const fundQ=ensureFundamentalQuality(mcapStock)
  const [resultRating,setResultRating]=useState(null)
  const [mcapFallback,setMcapFallback]=useState(null)
  useEffect(()=>{
    let cancelled=false
    setResultRating(null)
    setMcapFallback(null)
    if(!sym) return
    const needMcap=mcapStock?.marketCap==null
    Promise.all([
      fetchFinancialResultsHistory(sym).catch(()=>null),
      needMcap ? fetchStockFundamentals(sym).catch(()=>null) : Promise.resolve(null),
    ]).then(([hist, fund])=>{
      if(cancelled) return
      setResultRating(computeResultRating(hist)||null)
      const fromFund=fund?.market_cap ?? fund?.marketCap
      if(fromFund!=null && isFinite(+fromFund)) setMcapFallback(+fromFund)
    })
    return ()=>{ cancelled=true }
  },[sym, mcapStock?.marketCap])
  const mcapLabel=fmtMarketCapCr(mcapStock?.marketCap ?? mcapFallback)
  const resultCol=resultRatingColor(resultRating)
  const renderBlock=(sectionId)=>{
    if(sectionId==='mcap'){
      // One line: Market Cap · Fundamental · Result
      return (
        <div style={{
          marginBottom:10, display:'flex', alignItems:'center', gap:8,
          flexWrap:'nowrap', overflowX:'auto', WebkitOverflowScrolling:'touch',
        }}>
          <span style={{
            fontSize:11, fontWeight:700, color:C.text, whiteSpace:'nowrap',
            padding:'4px 10px', borderRadius:999, border:`1px solid ${C.border}`, background:C.card,
          }} title="Market capitalization">
            MCap <span style={{color:mcapLabel?C.muted:C.muted,fontWeight:600}}>
              {mcapLabel || '—'}
            </span>
          </span>
          <button type="button" onClick={()=>setDetailTab?.('fundamentals')}
            title="Overall fundamental quality — open Fundamentals"
            style={{
              fontSize:11, fontWeight:800, whiteSpace:'nowrap', cursor:'pointer',
              color: fundQ.label ? fundLabelColor(fundQ.label) : C.muted,
              background: fundQ.label ? fundLabelColor(fundQ.label)+'22' : 'transparent',
              border:`1px ${fundQ.label?'solid':'dashed'} ${fundQ.label?fundLabelColor(fundQ.label)+'55':C.border}`,
              borderRadius:999, padding:'4px 10px',
            }}>
            Fundamental {fundQ.label||'—'}{fundQ.label&&fundQ.score!=null?` ${Math.round(fundQ.score)}`:''}
          </button>
          <button type="button" onClick={()=>setDetailTab?.('results')}
            title="Latest-quarter Result quality — open Results"
            style={{
              fontSize:11, fontWeight:800, whiteSpace:'nowrap', cursor:'pointer',
              color: resultRating ? resultCol : C.muted,
              background: resultRating ? resultCol+'22' : 'transparent',
              border:`1px ${resultRating?'solid':'dashed'} ${resultRating?resultCol+'55':C.border}`,
              borderRadius:999, padding:'4px 10px',
            }}>
            Result {resultRating ? `- ${resultRating}` : '—'}
          </button>
        </div>
      )
    }
    if(sectionId==='peers'){
      // Result-quality peer ranking — under MCap; height-capped so About/Results stay scrollable.
      return (
        <div style={{marginBottom:8, height:'100%', minHeight:0}}>
          <SectorRankingPanel symbol={sym}
            industry={mcapStock?.industry}
            stocks={stocks}
            onSelectSymbol={(s)=>navigateTo?.(s,{openResults:true})}/>
        </div>
      )
    }
    if(sectionId==='themes') return <div style={{marginBottom:10}}><StockThemesAfterMcap symbol={sym}/></div>
    if(sectionId==='mgmt') return <div style={{marginBottom:10}}><MgmtFlagsCard symbol={sym} compact/></div>
    return null
  }
  const belowPad='8px 14px 14px'
  // fillParent: Details PanelWindow already scrolls (scrollBody) — content is document-flow.
  // Otherwise (mobile): this root fills remaining space and scrolls.
  return (
    <div style={{
      flex: fillParent ? undefined : 1,
      minHeight: fillParent ? undefined : 0,
      display: 'flex',
      flexDirection: 'column',
      overflowX: 'hidden',
      overflowY: fillParent ? 'visible' : 'auto',
      WebkitOverflowScrolling: 'touch',
      overscrollBehavior: 'contain',
      padding: belowPad,
      borderTop: fillParent ? 'none' : `1px solid ${C.divider}`,
      background: C.bg,
      height: fillParent ? 'auto' : '100%',
      boxSizing: 'border-box',
    }}>
      <div style={{flexShrink:0, position:'sticky', top:0, zIndex:8, background:C.bg, paddingBottom:2}}>
        <div style={{display:'flex',justifyContent:'flex-end',marginBottom:customizeOpen?8:4}}>
          <button type="button" onClick={()=>setCustomizeOpen(v=>!v)}
            style={{padding:'4px 10px',borderRadius:6,border:`1px solid ${customizeOpen?C.accent:C.border}`,
              background:customizeOpen?C.accent+'18':'transparent',color:customizeOpen?C.accent:C.muted,
              fontSize:10,fontWeight:700,cursor:'pointer'}}>
            {customizeOpen?'Done':'Show / hide blocks'}
          </button>
        </div>
        {customizeOpen&&(
          <div style={{marginBottom:12,padding:'10px 12px',borderRadius:10,
            border:`1px solid ${C.border}`,background:C.card}}>
            <div style={{display:'flex',alignItems:'flex-start',gap:8,marginBottom:8}}>
              <div style={{flex:1,fontSize:10,color:C.muted}}>
                Hide blocks you don&apos;t want (saved with your layout). Drag to reorder visible ones.
              </div>
              <button type="button"
                onClick={()=>{
                  onSectionHiddenChange?.([])
                  onSectionOrderChange?.(normalizeChartSectionOrder(CHART_SECTION_ORDER_DEFAULT))
                }}
                disabled={hiddenSet.size===0}
                title="Bring back every block and restore the default order"
                style={{padding:'4px 8px',borderRadius:6,flexShrink:0,
                  border:`1px solid ${hiddenSet.size?C.accent:C.border}`,
                  background:'transparent',color:hiddenSet.size?C.accent:C.muted,
                  fontSize:10,fontWeight:700,cursor:hiddenSet.size?'pointer':'default',
                  opacity:hiddenSet.size?1:0.5}}>
                Show all
              </button>
            </div>
            <div style={{display:'flex',flexWrap:'wrap',gap:6,marginBottom:10}}>
              {CHART_SECTION_ORDER_DEFAULT.map(key=>{
                const on=!hiddenSet.has(key)
                return (
                  <button key={key} type="button"
                    onClick={()=>{
                      const next=on
                        ? [...new Set([...(sectionHidden||[]), key])]
                        : (sectionHidden||[]).filter(k=>k!==key)
                      onSectionHiddenChange?.(normalizeChartSectionHidden(next))
                    }}
                    style={{padding:'5px 10px',borderRadius:999,fontSize:10,fontWeight:700,cursor:'pointer',
                      border:`1px solid ${on?C.accent:C.border}`,
                      background:on?C.accent+'18':'transparent',
                      color:on?C.accent:C.muted}}>
                    {on?'✓':'○'} {CHART_SECTION_LABELS[key]||key}
                  </button>
                )
              })}
            </div>
            <ReorderableList items={sectionOrder} onReorder={onSectionOrderChange}
              hint="Change the order of content below the chart."
              renderItem={(key)=>(
                <div style={{display:'flex',alignItems:'center',gap:8,flex:1,minWidth:0}}>
                  <span style={{fontSize:12,fontWeight:700,color:C.text}}>{CHART_SECTION_LABELS[key]||key}</span>
                  <span style={{fontSize:10,color:C.muted}}>{hiddenSet.has(key)?'Hidden':'Visible'}</span>
                </div>
              )}/>
          </div>
        )}
      </div>
      {visibleSections.length===0&&(
        <div style={{padding:'18px 4px',fontSize:11,color:C.muted,lineHeight:1.6}}>
          Every block below the chart is hidden.
          {' '}
          <button type="button"
            onClick={()=>{
              setCustomizeOpen(true)
              onSectionHiddenChange?.([])
            }}
            style={{padding:0,border:'none',background:'transparent',color:C.accent,
              fontSize:11,fontWeight:700,cursor:'pointer',textDecoration:'underline'}}>
            Show them again
          </button>
        </div>
      )}
      {visibleSections.map(sectionId=>{
        if(sectionId==='details'){
          return (
            <div key="details" style={{paddingBottom:32}}>
              <StockDetailTabs sym={sym} stocks={stocks} tab={detailTab} setTab={setDetailTab}
                onSelectSymbol={(s)=>navigateTo(s,{openResults:true})} scrollable={false} isMobile={isMobile}/>
            </div>
          )
        }
        const block=renderBlock(sectionId)
        return block?(
          <div key={sectionId} style={sectionId==='peers'?{maxHeight:isMobile?110:130,marginBottom:8,overflow:'hidden'}:undefined}>
            {block}
          </div>
        ):null
      })}
    </div>
  )
}

function TradingViewDailyChart({symbol, exchange, onReady}){
  // Advanced Chart widget — widgetembed often ignored interval=D and opened on 60m.
  const wrapRef = useRef(null)
  useEffect(()=>{
    const wrap = wrapRef.current
    if(!wrap || !symbol) return
    wrap.innerHTML = ''
    const widgetHost = document.createElement('div')
    widgetHost.className = 'tradingview-widget-container__widget'
    widgetHost.style.height = '100%'
    widgetHost.style.width = '100%'
    wrap.appendChild(widgetHost)
    const script = document.createElement('script')
    script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js'
    script.type = 'text/javascript'
    script.async = true
    script.text = JSON.stringify({
      autosize: true,
      symbol: `${exchange}:${symbol}`,
      interval: '1D',
      timezone: 'Asia/Kolkata',
      theme: 'dark',
      style: '1',
      locale: 'en',
      backgroundColor: '#0e1117',
      toolbar_bg: '#0e1117',
      enable_publishing: false,
      hide_top_toolbar: false,
      hide_legend: false,
      hide_side_toolbar: false,
      allow_symbol_change: true,
      save_image: false,
      withdateranges: true,
      calendar: false,
      studies: [
        'RSI@tv-basicstudies',
        'Volume@tv-basicstudies',
        'MACD@tv-basicstudies',
      ],
      support_host: 'https://www.tradingview.com',
    })
    wrap.appendChild(script)
    const t = setTimeout(()=>onReady?.(), 800)
    return ()=>{
      clearTimeout(t)
      wrap.innerHTML = ''
    }
  }, [symbol, exchange]) // eslint-disable-line react-hooks/exhaustive-deps
  return (
    <div ref={wrapRef} className="tradingview-widget-container"
      style={{height:'100%', width:'100%', minHeight:0}}/>
  )
}

function ChartPanel({sym, isIndex, wide, customPct, onToggleWide, onClose, isMobile, symList, onNavigate, stocks, chartSectionOrder, chartSectionHidden=[], onChartSectionOrderChange, onChartSectionHiddenChange, panelChart, panelDetail, onPanelChart, onPanelDetail, expandCol=false, detailTabHint=null, onConsumeDetailTabHint, chartTabHint=null, onConsumeChartTabHint, detailFirst=false, onMoveTile, stackLayout=false, columnsLayout=false, chartColPct=36, detailColPct=32, sideSoloChart=false, chartCellStyle=null, detailCellStyle=null, chartStackOrder=2, detailStackOrder=4, userId=null}){
  const [loaded, setLoaded] = useState(false)
  // Stocks open on TradingView (1D); indices only have Our Chart.
  const [chartTab, setChartTab] = useState('own') // 'own' | 'tv' — Our Chart first (Super Cycle, drawings, …)
  const sectionOrder=normalizeChartSectionOrder(chartSectionOrder)
  const sectionHidden=normalizeChartSectionHidden(chartSectionHidden)
  const persistSectionOrder=(order)=>{
    onChartSectionOrderChange?.(normalizeChartSectionOrder(order))
  }
  const persistSectionHidden=(hidden)=>{
    onChartSectionHiddenChange?.(normalizeChartSectionHidden(hidden))
  }
  // Peer ranking pills open Results; catch-up / history can open PPT/Concall/Results Summary.
  const [detailTab, setDetailTab] = useState('about')
  // Phones are chart-first: the Overview sits below as a peeking sheet the
  // user pulls up to read, rather than permanently eating a third of the screen.
  const [mobileOverviewOpen, setMobileOverviewOpen] = useState(false)
  const openResultsOnNavRef = useRef(false)
  const pendingDetailTabRef = useRef(null)
  useEffect(()=>{ if(isIndex) setChartTab('own') },[isIndex])
  useEffect(()=>{ setMobileOverviewOpen(false) },[sym])
  useEffect(()=>{
    if(chartTabHint==='own' || chartTabHint==='tv'){
      if(isIndex) setChartTab('own')
      else setChartTab(chartTabHint)
      onConsumeChartTabHint?.()
    }
  },[sym, chartTabHint, isIndex]) // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(()=>{
    if(detailTabHint){
      setDetailTab(detailTabHint)
      setMobileOverviewOpen(true)
      onConsumeDetailTabHint?.()
      return
    }
    if(pendingDetailTabRef.current){
      setDetailTab(pendingDetailTabRef.current)
      setMobileOverviewOpen(true)
      pendingDetailTabRef.current = null
      return
    }
    if(openResultsOnNavRef.current){
      setDetailTab('results')
      setMobileOverviewOpen(true)
      // Delay clear so React Strict Mode's double-effect still sees the flag.
      queueMicrotask(()=>{ openResultsOnNavRef.current = false })
    } else {
      setDetailTab('about')
    }
  },[sym, detailTabHint]) // eslint-disable-line react-hooks/exhaustive-deps
  const navigateTo = (nextSym, {openResults=false, openTab=null}={})=>{
    if(!nextSym || !onNavigate) return
    if(openTab){
      pendingDetailTabRef.current = openTab
      setDetailTab(openTab)
    } else {
      openResultsOnNavRef.current = !!openResults
      if(openResults) setDetailTab('results')
    }
    onNavigate(nextSym)
  }
  // is the default: NSE restricted its symbols in TradingView's embeddable
  // widget ("This symbol is only available on TradingView" even for major
  // stocks), so the embed frequently fails. BSE listings still work in
  // embeds — the TV tab defaults to BSE with an exchange toggle.
  const [tvExchange, setTvExchange] = useState('BSE')
  useEffect(() => { setLoaded(false) }, [sym, tvExchange])

  if(!sym) return null

  // Prev/Next within whatever list was showing when the chart was
  // opened — so you can flip through stocks one by one without closing
  // the panel and re-picking from the (often full-screen-hidden, on
  // mobile) list each time.
  const idx = symList ? symList.indexOf(sym) : -1
  const prevSym = idx > 0 ? symList[idx-1] : null
  const nextSym = idx >= 0 && idx < (symList?.length||0)-1 ? symList[idx+1] : null

  const panelStyle = isMobile
    ? {position:'fixed',inset:0,zIndex:1000,display:'flex',flexDirection:'column',background:C.sidebar}
    : {position:'relative',flex:expandCol?1:(customPct!=null?`0 0 ${customPct}%`:(['0 0 35%','0 0 50%','0 0 75%'][wide]||'0 0 35%')),
        height:'100%',alignSelf:'stretch',overflow:'hidden',
        display:'flex',flexDirection:'column',background:C.sidebar,
        borderLeft:`1px solid ${C.divider}`,transition:customPct!=null||expandCol?'none':'flex 0.2s ease'}
  // In stack mode, Chart and Details are independent flex siblings of the RS table
  // (so Overview can sit directly under the RS rating table).
  const stackTileStyle=(order, flexGrow, minH=180)=>({
    position:'relative',
    flex: flexGrow,
    minHeight: minH,
    alignSelf:'stretch',
    overflow:'hidden',
    display:'flex',
    flexDirection:'column',
    background:C.sidebar,
    borderTop:`1px solid ${C.divider}`,
    order,
  })
  // Three-column mode: RS | Chart | Fundamentals as equal-height columns.
  const columnsTileStyle=(order, pct)=>({
    position:'relative',
    flex: `0 0 ${pct}%`,
    minWidth:160,
    minHeight:0,
    height:'100%',
    alignSelf:'stretch',
    overflow:'hidden',
    display:'flex',
    flexDirection:'column',
    background:C.sidebar,
    borderLeft:`1px solid ${C.divider}`,
    order,
  })
  // Chart full-height on one side; RS + Overview share the opposite column (CSS grid parent).
  const soloChartTileStyle={
    position:'relative',
    minWidth:0,minHeight:0,overflow:'hidden',
    display:'flex',flexDirection:'column',background:C.sidebar,
    ...(chartCellStyle||{}),
  }
  const soloDetailTileStyle={
    position:'relative',
    minWidth:0,minHeight:0,overflow:'hidden',
    display:'flex',flexDirection:'column',background:C.bg,
    borderTop:`1px solid ${C.divider}`,
    ...(detailCellStyle||{}),
  }

  const chartExpanded=wide>=1||(customPct!=null&&customPct>=45)
  const readingMode=['about','fundamentals','concall','ppt','resultsSummary'].includes(detailTab)
  const tableMode=detailTab==='results'
  // Chart always keeps the larger share; Details scrolls in the remaining space.
  const chartFlex=readingMode?'1 1 62%':tableMode?'1 1 65%':'1 1 70%'
  const chartMaxH=undefined
  const belowFlex=readingMode?'0 1 38%':tableMode?'0 1 35%':'0 1 30%'
  const belowMin=readingMode?150:tableMode?140:120
  const chartMinH=readingMode?200:tableMode?220:240

  const chartHeaderExtra=(
    <div style={{display:'flex',alignItems:'center',gap:6}} onMouseDown={e=>e.stopPropagation()}>
      <button type="button" onClick={()=>prevSym&&navigateTo(prevSym)} disabled={!prevSym}
        title="Previous stock"
        style={{background:'transparent',border:`1px solid ${C.border}`,
          color:prevSym?C.text:C.border,fontSize:12,width:22,height:20,borderRadius:4,
          cursor:prevSym?'pointer':'default',display:'flex',alignItems:'center',justifyContent:'center'}}>
        ◀
      </button>
      <button type="button" onClick={()=>nextSym&&navigateTo(nextSym)} disabled={!nextSym}
        title="Next stock"
        style={{background:'transparent',border:`1px solid ${C.border}`,
          color:nextSym?C.text:C.border,fontSize:12,width:22,height:20,borderRadius:4,
          cursor:nextSym?'pointer':'default',display:'flex',alignItems:'center',justifyContent:'center'}}>
        ▶
      </button>
      <a href={`https://www.tradingview.com/chart/?symbol=${tvExchange}:${sym}`}
        target="_blank" rel="noopener noreferrer"
        title="Open in TradingView"
        style={{fontSize:10,color:C.accent,textDecoration:'none',
          padding:'2px 6px',borderRadius:4,border:`1px solid ${C.accent}33`}}>
        TV ↗
      </a>
      {!isMobile&&(
        <button type="button" onClick={onToggleWide}
          title={['Expand chart','Expand further','Back to normal'][wide]}
          style={{background:'transparent',border:`1px solid ${C.border}`,
            color:C.muted,fontSize:10,padding:'2px 6px',borderRadius:4,
            cursor:'pointer',whiteSpace:'nowrap'}}>
          {['◀◀','◀◀◀','▶▶▶'][wide]}
        </button>
      )}
    </div>
  )

  const chartTabsAndBody=(
    <div style={{flex:1,minHeight:0,display:'flex',flexDirection:'column',overflow:'hidden'}}>
      <div style={{display:'flex',gap:0,borderBottom:`1px solid ${C.divider}`,flexShrink:0}}>
        {(isIndex?[['own','Our Chart']]:[['own','Our Chart'],['tv','TradingView']]).map(([v,label])=>(
          <button key={v} type="button" onClick={()=>setChartTab(v)}
            style={{flex:1,padding:'8px 0',fontSize:11,fontWeight:700,cursor:'pointer',
              background:chartTab===v?C.card:'transparent',
              color:chartTab===v?C.accent:C.muted,
              border:'none',borderBottom:chartTab===v?`2px solid ${C.accent}`:'2px solid transparent'}}>
            {label}
          </button>
        ))}
      </div>
      {chartTab==='tv'&&(
        <div style={{display:'flex',flexWrap:'wrap',alignItems:'center',gap:6,padding:'6px 14px',
          borderBottom:`1px solid ${C.divider}`,flexShrink:0}}>
          <span style={{fontSize:10,color:C.muted}}>Exchange:</span>
          {['BSE','NSE'].map(ex=>(
            <button key={ex} type="button"
              onClick={()=>{
                if(ex==='NSE'){
                  // Free TradingView embeds cannot license NSE — opening full TV instead.
                  window.open(`https://www.tradingview.com/chart/?symbol=NSE:${encodeURIComponent(sym)}`,'_blank','noopener,noreferrer')
                  return
                }
                setTvExchange(ex)
                setLoaded(false)
              }}
              title={ex==='NSE'?'NSE is blocked inside embeds by TradingView — opens full TradingView':'BSE works in the in-app chart'}
              style={{padding:'2px 10px',borderRadius:6,border:`1px solid ${tvExchange===ex?C.accent:C.border}`,
                background:tvExchange===ex?C.accent+'22':'transparent',
                color:tvExchange===ex?C.accent:C.muted,fontSize:10,fontWeight:700,cursor:'pointer'}}>
              {ex}{ex==='NSE'?' ↗':''}
            </button>
          ))}
          <span style={{fontSize:9,color:C.muted,flex:'1 1 160px',lineHeight:1.35}}>
            In-app chart uses <b style={{color:C.text,fontWeight:700}}>BSE</b> (TradingView blocks NSE in free embeds).
            NSE opens the full TradingView site.
          </span>
        </div>
      )}
      <div style={{flex:1,minHeight:0,position:'relative',overflow:'hidden',
        display:'flex',flexDirection:'column'}}>
        {chartTab==='tv'?(
          <>
            {!loaded&&(
              <div style={{position:'absolute',inset:0,display:'flex',alignItems:'center',
                justifyContent:'center',flexDirection:'column',gap:8,background:C.sidebar,zIndex:1}}>
                <div style={{fontSize:12,color:C.muted}}>Loading {sym} chart…</div>
              </div>
            )}
            <TradingViewDailyChart
              key={`BSE:${sym}:1D`}
              symbol={sym}
              exchange="BSE"
              onReady={()=>setLoaded(true)}
            />
          </>
        ):(
          <CandlestickChart sym={sym} isMobile={isMobile} isIndex={isIndex} chartExpanded={chartExpanded} userId={userId}/>
        )}
      </div>
    </div>
  )

  const detailBody=!isIndex?(
    <ChartBelowContent sym={sym} stocks={stocks} sectionOrder={sectionOrder}
      sectionHidden={sectionHidden}
      onSectionOrderChange={persistSectionOrder}
      onSectionHiddenChange={persistSectionHidden}
      detailTab={detailTab} setDetailTab={setDetailTab}
      navigateTo={navigateTo} isMobile={isMobile} readingMode={readingMode} tableMode={tableMode}
      fillParent={!isMobile}/>
  ):null

  // Mobile: keep fullscreen stacked layout (no floating windows).
  if(isMobile){
    return(
      <div style={panelStyle}>
        <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',
          padding:'14px 14px 8px',borderBottom:`1px solid ${C.divider}`,flexShrink:0,height:48}}>
          <div style={{display:'flex',alignItems:'center',gap:6}}>
            <button onClick={()=>prevSym&&navigateTo(prevSym)} disabled={!prevSym}
              title="Previous stock"
              style={{background:'transparent',border:`1px solid ${C.border}`,
                color:prevSym?C.text:C.border,fontSize:13,width:26,height:26,borderRadius:4,
                cursor:prevSym?'pointer':'default',display:'flex',alignItems:'center',justifyContent:'center'}}>
              ◀
            </button>
            <span style={{fontWeight:700,fontSize:14,color:C.text,letterSpacing:'0.01em'}}>{sym}</span>
            <button onClick={()=>nextSym&&navigateTo(nextSym)} disabled={!nextSym}
              title="Next stock"
              style={{background:'transparent',border:`1px solid ${C.border}`,
                color:nextSym?C.text:C.border,fontSize:13,width:26,height:26,borderRadius:4,
                cursor:nextSym?'pointer':'default',display:'flex',alignItems:'center',justifyContent:'center'}}>
              ▶
            </button>
            <a href={`https://www.tradingview.com/chart/?symbol=${tvExchange}:${sym}`}
              target="_blank" rel="noopener noreferrer"
              style={{fontSize:10,color:C.accent,textDecoration:'none',
                padding:'2px 7px',borderRadius:4,border:`1px solid ${C.accent}33`}}>
              TV ↗
            </a>
          </div>
          <button onClick={onClose}
            style={{background:'transparent',border:`1px solid ${C.border}`,
              color:C.muted,fontSize:16,width:26,height:26,borderRadius:4,
              cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center',
              lineHeight:1}}>×
          </button>
        </div>
        <div style={{
          flex: detailBody ? (mobileOverviewOpen ? '0 0 42%' : '1 1 86%') : '1 1 100%',
          minHeight: mobileOverviewOpen ? 180 : 300,
          position:'relative',overflow:'hidden',
          display:'flex',flexDirection:'column'}}>
          {chartTabsAndBody}
        </div>
        {detailBody&&(
          <>
            {/* Grab bar: the Overview's only job when collapsed is to say it's
                there and open on one tap. */}
            <button type="button"
              onClick={()=>setMobileOverviewOpen(o=>!o)}
              title={mobileOverviewOpen?'Collapse company overview':'Expand company overview'}
              style={{flexShrink:0,display:'flex',alignItems:'center',justifyContent:'center',gap:8,
                width:'100%',padding:'6px 12px',border:'none',
                borderTop:`1px solid ${C.divider}`,borderBottom:`1px solid ${C.divider}`,
                background:C.card,color:C.muted,fontSize:11,fontWeight:700,
                cursor:'pointer',fontFamily:'inherit'}}>
              <span style={{width:26,height:3,borderRadius:2,background:C.border}}/>
              {mobileOverviewOpen?'▾ Hide overview':'▴ Company overview'}
              <span style={{width:26,height:3,borderRadius:2,background:C.border}}/>
            </button>
            <div style={{
              flex: mobileOverviewOpen ? 1 : '0 0 0px',
              minHeight:0,overflow:'hidden',display:'flex',flexDirection:'column'}}>
              {detailBody}
            </div>
          </>
        )}
      </div>
    )
  }

  const winChart=panelChart||{open:true,minimized:false,float:null}
  const winDetail=panelDetail||{open:true,minimized:false,float:null}
  const chartDocked=winChart.open&&!winChart.minimized&&!winChart.float
  const detailDocked=!isIndex&&winDetail.open&&!winDetail.minimized&&!winDetail.float
  const anyDocked=chartDocked||detailDocked

  const patchChart=(patch)=>{
    onPanelChart?.(patch)
    if(patch.open===false&&(!winDetail.open||isIndex)) onClose?.()
  }
  const patchDetail=(patch)=>{
    onPanelDetail?.(patch)
    if(patch.open===false&&!winChart.open) onClose?.()
  }

  const chartWin=(bundled)=>(
    chartDocked?(
      <PanelWindow
        key="chart-dock"
        id="chart"
        title={`${sym} · Chart`}
        colors={C}
        floating={null}
        onFloatingChange={f=>onPanelChart?.({float:f})}
        onMinimize={()=>onPanelChart?.({minimized:true})}
        onClose={()=>patchChart({open:false})}
        headerExtra={chartHeaderExtra}
        onMoveUp={onMoveTile?()=>onMoveTile('chart',-1):null}
        onMoveDown={onMoveTile?()=>onMoveTile('chart',1):null}
        dockStyle={{
          flex: bundled && detailDocked ? chartFlex : 1,
          minHeight: chartMinH,
          maxHeight: bundled && detailDocked ? chartMaxH : undefined,
          border:'none',borderRadius:0,background:C.sidebar,
          height: bundled ? undefined : '100%',
        }}
        zIndex={40}
      >
        {chartTabsAndBody}
      </PanelWindow>
    ):null
  )
  const detailWin=(bundled)=>(
    detailDocked?(
      <PanelWindow
        key="detail-dock"
        id="detail"
        title={`${sym} · Fundamentals`}
        colors={C}
        floating={null}
        onFloatingChange={f=>onPanelDetail?.({float:f})}
        onMinimize={()=>onPanelDetail?.({minimized:true})}
        onClose={()=>patchDetail({open:false})}
        onMoveUp={onMoveTile?()=>onMoveTile('detail',-1):null}
        onMoveDown={onMoveTile?()=>onMoveTile('detail',1):null}
        scrollBody
        dockStyle={{
          flex: bundled && chartDocked ? belowFlex : 1,
          minHeight:belowMin,
          border:'none',borderRadius:0,background:C.bg,
          borderTop:(bundled&&chartDocked&&!detailFirst)?`1px solid ${C.divider}`:'none',
          borderBottom:(bundled&&chartDocked&&detailFirst)?`1px solid ${C.divider}`:'none',
          height: bundled ? undefined : '100%',
        }}
        zIndex={41}
      >
        {detailBody}
      </PanelWindow>
    ):null
  )

  return(
    <>
      {anyDocked&&stackLayout&&(
        <>
          {chartDocked&&(
            <div style={stackTileStyle(chartStackOrder, '1 1 62%', chartMinH)}>
              {chartWin(false)}
            </div>
          )}
          {detailDocked&&(
            <div style={stackTileStyle(detailStackOrder, '0 1 34%', belowMin)}>
              {detailWin(false)}
            </div>
          )}
        </>
      )}
      {anyDocked&&!stackLayout&&columnsLayout&&(
        <>
          {chartDocked&&(
            <div style={columnsTileStyle(chartStackOrder, chartColPct)}>
              {chartWin(false)}
            </div>
          )}
          {detailDocked&&(
            <div style={{...columnsTileStyle(detailStackOrder, detailColPct), background:C.bg}}>
              {detailWin(false)}
            </div>
          )}
        </>
      )}
      {anyDocked&&!stackLayout&&!columnsLayout&&sideSoloChart&&(
        <>
          {chartDocked&&(
            <div style={soloChartTileStyle}>
              {chartWin(false)}
            </div>
          )}
          {detailDocked&&(
            <div style={soloDetailTileStyle}>
              {detailWin(false)}
            </div>
          )}
        </>
      )}
      {anyDocked&&!stackLayout&&!columnsLayout&&!sideSoloChart&&(
        <div style={panelStyle}>
          {detailFirst ? <>{detailWin(true)}{chartWin(true)}</> : <>{chartWin(true)}{detailWin(true)}</>}
        </div>
      )}
      {winChart.open&&!winChart.minimized&&winChart.float&&(
        <PanelWindow
          id="chart-float"
          title={`${sym} · Chart`}
          colors={C}
          floating={winChart.float}
          onFloatingChange={f=>onPanelChart?.({float:f})}
          onMinimize={()=>onPanelChart?.({minimized:true})}
          onClose={()=>patchChart({open:false})}
          headerExtra={chartHeaderExtra}
          zIndex={80}
        >
          {chartTabsAndBody}
        </PanelWindow>
      )}
      {!isIndex&&winDetail.open&&!winDetail.minimized&&winDetail.float&&(
        <PanelWindow
          id="detail-float"
          title={`${sym} · Fundamentals`}
          colors={C}
          floating={winDetail.float}
          onFloatingChange={f=>onPanelDetail?.({float:f})}
          onMinimize={()=>onPanelDetail?.({minimized:true})}
          onClose={()=>patchDetail({open:false})}
          scrollBody
          zIndex={81}
        >
          {detailBody}
        </PanelWindow>
      )}
    </>
  )
}

// AI summary of the official results-filing PDF (concall_summaries table).
// Distinct from numeric Results + structured Concall/PPT reports.
function ResultsFilingSummary({symbol}){
  const [rows, setRows] = useState(null) // null=loading, []=none, array=loaded
  const [expanded, setExpanded] = useState(false)
  const [selectedIdx, setSelectedIdx] = useState(0)
  useEffect(() => {
    let cancelled = false
    setRows(null)
    setExpanded(false)
    setSelectedIdx(0)
    if (!symbol) return
    fetchConcallSummaries(symbol).then(r => { if (!cancelled) setRows(r) })
    return () => { cancelled = true }
  }, [symbol])
  if (rows === null) {
            return (
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:'20px 14px',
        textAlign:'center',color:C.muted,fontSize:12}}>
        Loading results summary…
              </div>
            )
  }
  if (rows.length === 0) {
    return (
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:'20px 14px',
        textAlign:'center'}}>
        <div style={{fontSize:13,fontWeight:700,color:C.text,marginBottom:6}}>No results summary yet</div>
        <div style={{fontSize:11.5,color:C.muted,lineHeight:1.5}}>
          When a quarterly results PDF is filed for {symbol}, the server reads it and writes an AI summary here.
        </div>
      </div>
    )
  }
  const latest = rows[Math.min(selectedIdx, rows.length - 1)]
  const dateLabel = new Date(latest.announced_at).toLocaleDateString('en-IN',
    {day:'numeric', month:'short', year:'numeric'})
  return (
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,overflow:'hidden',
      boxShadow:'0 2px 12px rgba(0,0,0,0.25)'}}>
      <div style={{height:4,background:`linear-gradient(90deg, ${C.green}, ${C.teal}, ${C.blue})`}}/>
      <div style={{padding:'12px 14px'}}>
        <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:8,gap:8}}>
          <div style={{fontSize:12,fontWeight:900,color:C.text,display:'flex',alignItems:'center',gap:6}}>
            <span style={{fontSize:15}}>📄</span> AI Results Summary
          </div>
          <div style={{display:'flex',alignItems:'center',gap:8,flexShrink:0}}>
            <SectionFeedback symbol={symbol} contentType="results_summary" sectionKey="summary"
              sectionLabel="AI Results Summary"/>
            <div style={{fontSize:10,color:C.muted,fontWeight:600}}>{dateLabel}</div>
          </div>
        </div>
        <ReportHistoryPicker rows={rows} selectedIdx={selectedIdx}
          onSelect={i=>{ setSelectedIdx(i); setExpanded(false) }}/>
        <div style={{fontSize:12.5,lineHeight:1.55,color:C.text,
          display:'-webkit-box',WebkitLineClamp:expanded?'unset':6,WebkitBoxOrient:'vertical',overflow:'hidden'}}>
          {latest.summary}
        </div>
        <div style={{display:'flex',gap:12,marginTop:8,flexWrap:'wrap'}}>
          <span onClick={()=>setExpanded(e=>!e)} style={{fontSize:10,fontWeight:700,color:C.accent,cursor:'pointer'}}>
            {expanded?'Show less':'Show more'}
          </span>
          {latest.attachment_url&&(
            <a href={latest.attachment_url} target="_blank" rel="noopener noreferrer"
              style={{fontSize:10,fontWeight:700,color:C.accent}}>View original PDF ↗</a>
          )}
        </div>
        <div style={{fontSize:9,color:C.muted,marginTop:8,fontStyle:'italic'}}>
          AI-generated summary of the official results filing — may miss nuance. Not investment advice.
        </div>
      </div>
    </div>
  )
}

function fmtResultPeriod(label){
  if(!label||label==='—') return '—'
  const d=new Date(label)
  if(isNaN(d.getTime())) return String(label).length>12?String(label).slice(0,12)+'…':String(label)
  return d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'2-digit'})
}

function ResultsHistoryTable({symbol}){
  const [hist, setHist] = useState(undefined) // undefined=loading, []=no data, array=loaded
  useEffect(() => {
    let cancelled = false
    setHist(undefined)
    if (!symbol) return
    fetchFinancialResultsHistory(symbol).then(rows => { if (!cancelled) setHist(rows) })
    return () => { cancelled = true }
  }, [symbol])

  if (hist === undefined) {
    return <div style={{padding:'10px',fontSize:11,color:C.muted,textAlign:'center',
      background:C.card,border:`1px solid ${C.border}`,borderRadius:8}}>Loading results…</div>
  }
  if (hist.length === 0) {
    return <div style={{padding:'10px',fontSize:11,color:C.muted,textAlign:'center',
      background:C.card,border:`1px solid ${C.border}`,borderRadius:8}}>No results history yet.</div>
  }
  const current = hist[0]
  const prevQtr = hist[1] || null
  const curDate = new Date(current.period_ended)
  const yoyRow = hist.slice(1).find(h=>{
    const d = new Date(h.period_ended)
    const yearsBack = curDate.getFullYear()-d.getFullYear()
    const dayDiff = Math.abs((d.getMonth()*30+d.getDate())-(curDate.getMonth()*30+curDate.getDate()))
    return yearsBack===1 && dayDiff<=20
  }) || null
  const cols = [
    {label:fmtResultPeriod(current.period_ended), title:current.period_ended, row:current},
    {label:prevQtr?fmtResultPeriod(prevQtr.period_ended):'—', title:prevQtr?.period_ended, row:prevQtr},
    {label:yoyRow?fmtResultPeriod(yoyRow.period_ended):'—', title:yoyRow?.period_ended, row:yoyRow},
  ]
  const pct=(now,then)=>(now==null||then==null||then===0)?null:((now-then)/Math.abs(then)*100)
  const opm = effectiveOpm
  const qoqFor = (metric, backendVal) => backendVal != null ? backendVal : pct(metric(current), metric(prevQtr))
  const metrics = [
    {label:'Sales (₹Cr)', get:r=>r?.sales, yoyPct:pct(current.sales, yoyRow?.sales),
      qoqPct:qoqFor(r=>r?.sales, current.sales_qoq_pct)},
    {label:'Other Income (₹Cr)', get:r=>r?.other_income, yoyPct:pct(current.other_income, yoyRow?.other_income),
      qoqPct:pct(current.other_income, prevQtr?.other_income)},
    {label:'OPM %', get:opm, yoyPct:pct(opm(current), opm(yoyRow)), isPct:true,
      qoqPct:pct(opm(current), opm(prevQtr))},
    {label:'PBT (₹Cr)',   get:r=>r?.pbt,   yoyPct:pct(current.pbt,   yoyRow?.pbt),
      qoqPct:pct(current.pbt, prevQtr?.pbt)},
    {label:'PAT (₹Cr)',   get:r=>r?.pat,   yoyPct:pct(current.pat,   yoyRow?.pat),
      qoqPct:qoqFor(r=>r?.pat, current.pat_qoq_pct)},
    {label:'EPS (₹)',     get:r=>r?.eps,   yoyPct:pct(current.eps,   yoyRow?.eps),
      qoqPct:pct(current.eps, prevQtr?.eps)},
  ]
  const otherIncomeSpike = (current.other_income!=null && prevQtr?.other_income!=null &&
    prevQtr.other_income>0.5 && current.other_income > prevQtr.other_income*1.5)
  const resultRating = computeResultRating(hist)
  return (
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:8,padding:'8px 10px',overflowX:'auto'}}>
      <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8,marginBottom:6,flexWrap:'wrap'}}>
        <div style={{display:'flex',alignItems:'center',gap:6,flexWrap:'wrap'}}>
      {resultRating&&(
            <div title="Quality from Sales/PAT YoY. Capped if headline PAT fell, OPM compressed, or QoQ is flat/soft — strong YoY alone is not Excellent. Not a buy/sell call."
              style={{display:'inline-block',padding:'2px 9px',borderRadius:12,
            fontSize:10,fontWeight:800,cursor:'help',
            background:(resultRating==='Excellent'?C.green:resultRating==='Good'?'#7dd3a8':
              resultRating==='Weak'?C.red:C.yellow)+'22',
            color:resultRating==='Excellent'?C.green:resultRating==='Good'?'#7dd3a8':
              resultRating==='Weak'?C.red:C.yellow}}>
          {resultRating==='Excellent'?'⭐ Excellent':resultRating==='Good'?'✓ Good':
            resultRating==='Weak'?'⚠ Weak':'– Neutral'} Result
        </div>
      )}
          <span style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:'uppercase',
            letterSpacing:'0.04em'}}>Results</span>
        </div>
        <SectionFeedback symbol={symbol} contentType="results" sectionKey="history_table"
          sectionLabel="Results table"/>
      </div>
      {otherIncomeSpike&&(
        <div title="Other income more than 50% higher than the previous quarter - worth checking whether this quarter's profit growth is coming from the core business or a one-time/non-operating gain."
          style={{display:'flex',alignItems:'center',gap:5,marginBottom:6,padding:'4px 9px',
            borderRadius:8,fontSize:10,fontWeight:700,cursor:'help',
            background:C.yellow+'18',color:C.yellow,border:`1px solid ${C.yellow}44`}}>
          ⚠ Other income jumped vs last quarter — check OPM% for the real operating trend
        </div>
      )}
      <table style={{width:'100%',fontSize:10.5,borderCollapse:'collapse',tableLayout:'fixed',minWidth:360}}>
        <colgroup>
          <col style={{width:'24%'}}/>
          <col style={{width:'11%'}}/>
          <col style={{width:'11%'}}/>
          <col style={{width:'18%'}}/>
          <col style={{width:'18%'}}/>
          <col style={{width:'18%'}}/>
        </colgroup>
        <thead>
          <tr>
            <th style={{textAlign:'left',fontWeight:700,color:C.muted,padding:'2px 6px'}}>Metric</th>
            <th style={{textAlign:'right',fontWeight:700,color:C.muted,padding:'2px 6px'}}>YoY</th>
            <th style={{textAlign:'right',fontWeight:700,color:C.muted,padding:'2px 6px'}}>QoQ</th>
            {cols.map((c,i)=>(
              <th key={i} title={c.title||c.label}
                style={{textAlign:'right',fontWeight:700,color:C.muted,padding:'2px 6px',whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>
                {c.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {metrics.map(m=>(
            <tr key={m.label} style={m.label==='Other Income (₹Cr)'&&otherIncomeSpike?
              {background:C.yellow+'0d'}:undefined}>
              <th scope="row" style={{textAlign:'left',color:m.label==='Other Income (₹Cr)'&&otherIncomeSpike?C.yellow:C.text,
                fontWeight:600,padding:'4px 6px',whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>
                {m.label==='Other Income (₹Cr)'&&otherIncomeSpike?'⚠ ':''}{m.label}
              </th>
              <td style={{textAlign:'right',padding:'4px 6px',fontWeight:700,
                color:m.yoyPct==null?C.muted:m.yoyPct>=0?C.green:C.red}}>
                {m.yoyPct==null?'—':`${m.yoyPct>=0?'▲':'▼'} ${Math.abs(m.yoyPct).toFixed(0)}%`}
              </td>
              <td style={{textAlign:'right',padding:'4px 6px',fontWeight:700,
                color:m.qoqPct==null?C.muted:m.qoqPct>=0?C.green:C.red}}>
                {m.qoqPct==null?'—':`${m.qoqPct>=0?'▲':'▼'} ${Math.abs(m.qoqPct).toFixed(0)}%`}
              </td>
              {cols.map((c,i)=>{
                const v = m.get(c.row)
                return (
                  <td key={i} style={{textAlign:'right',padding:'4px 6px',color:C.text,fontVariantNumeric:'tabular-nums',whiteSpace:'nowrap'}}>
                    {v==null?'—':m.isPct?`${v.toFixed(1)}%`:v.toLocaleString('en-IN',{maximumFractionDigits:2})}
                  </td>
                )
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

// Ranks a stock's result-quality rating (same computeResultRating() used
// everywhere else, so this always agrees with the badge shown above)
// against other stocks in the SAME INDUSTRY peer group (e.g. jewellery
// vs jewellery — not the whole Consumer Discretionary sector which mixes
// ACs, footwear, durables). Never falls back to sector/"Other" — those
// catch-alls mixed unrelated names (ALPHAGEO with BRITANNIA/OIL/CUPID).
// Capped to 40 peers by market cap.
const RATING_ORDER = {Excellent:3, Good:2, Neutral:1, Weak:0}
function SectorRankingPanel({symbol, industry, stocks, onSelectSymbol}){
  const [ranking, setRanking] = useState(undefined) // undefined=loading, null=no peers, array=loaded
  const peerGroup = getPeerGroup(symbol, industry)
  const groupLabel = (!isJunkIndustry(peerGroup) && peerGroup) || null
  useEffect(()=>{
    let cancelled = false
    setRanking(undefined)
    if(!symbol || !groupLabel || !stocks?.length){ setRanking(null); return }
    // Industry peer groups only (jewellery ↔ jewellery). getPeerGroup() also
    // groups shipbuilders (GRSE, MAZDOCK) under Shipping & Defence and splits
    // NSE's Pharma "Bulk Drugs & Formln" catch-all (IOLCP ≠ CIPLA).
    let peers = stocks
      .filter(s=>s.sym && getPeerGroup(s.sym, s.industry)===groupLabel)
      .sort((a,b)=>(b.marketCap??0)-(a.marketCap??0))
      .slice(0, 40)
    if(!peers.some(p=>p.sym===symbol)){
      const self = stocks.find(s=>s.sym===symbol)
      if(self) peers.push(self)
    }
    if(peers.length < 2){ setRanking(null); return }
    const peerBySym = Object.fromEntries(peers.map(p=>[p.sym,p]))
    Promise.all(peers.map(p=>
      fetchFinancialResultsHistory(p.sym).then(hist=>({
        sym:p.sym,
        rating:computeResultRating(hist),
        marketCap:p.marketCap ?? null,
        industry:p.industry || null,
      }))
    )).then(results=>{
      if(cancelled) return
      const rated = results.filter(r=>r.rating!=null)
        .sort((a,b)=>RATING_ORDER[b.rating]-RATING_ORDER[a.rating])
        .map(r=>({
          ...r,
          marketCap: r.marketCap ?? peerBySym[r.sym]?.marketCap ?? null,
        }))
      setRanking(rated.length>=2 ? rated : null)
    })
    return ()=>{cancelled=true}
  }, [symbol, industry, groupLabel, stocks])

  if(!groupLabel) return null
  if(ranking===undefined) return (
    <div style={{marginTop:4,fontSize:10.5,color:C.muted,padding:'2px 0'}}>
      Ranking vs {groupLabel} industry peers…
    </div>
  )
  if(ranking===null) return null
  const myIdx = ranking.findIndex(r=>r.sym===symbol)
  if(myIdx===-1) return null
  const ratingColor = r => r==='Excellent'?C.green:r==='Good'?'#7dd3a8':r==='Weak'?C.red:C.yellow
  return (
    <div style={{
      marginTop:0, background:C.card, border:`1px solid ${C.border}`, borderRadius:8,
      padding:'6px 8px', height:'100%', maxHeight:'100%',
      display:'flex', flexDirection:'column', minHeight:0, overflow:'hidden',
    }}>
      <div style={{fontSize:11,fontWeight:700,color:C.text,marginBottom:4,flexShrink:0}}>
        #{myIdx+1} of {ranking.length} rated in {groupLabel}
      </div>
      <div style={{
        display:'flex', flexWrap:'wrap', gap:4, alignContent:'flex-start',
        overflowY:'auto', overflowX:'hidden', minHeight:0, flex:1,
        WebkitOverflowScrolling:'touch',
      }}>
        {ranking.map((r,i)=>{
          const isSelf = r.sym===symbol
          const canOpen = !isSelf && typeof onSelectSymbol==='function'
          const mcap = fmtMarketCapCr(r.marketCap)
          return (
            <div key={r.sym}
              title={canOpen
                ? `${r.rating}${mcap?` · ${mcap}`:''} — open ${r.sym} Results`
                : `${r.rating}${mcap?` · ${mcap}`:''}`}
              onClick={()=>{ if(canOpen) onSelectSymbol(r.sym) }}
              style={{
                display:'inline-flex', alignItems:'center', gap:3,
                padding:'3px 7px', borderRadius:8,
                fontSize:10, fontWeight:isSelf?800:600, lineHeight:1.2,
                background:ratingColor(r.rating)+(isSelf?'33':'18'),
                color:ratingColor(r.rating),
                border:isSelf?`1px solid ${ratingColor(r.rating)}`:'1px solid transparent',
                cursor:canOpen?'pointer':'default',
                textDecoration:canOpen?'underline':'none', textUnderlineOffset:2,
                whiteSpace:'nowrap',
              }}>
              <span style={{opacity:0.7}}>#{i+1}</span> {r.sym}
              {mcap && <span style={{opacity:0.75,fontSize:9,fontWeight:600,color:C.muted}}>· {mcap.replace('₹','')}</span>}
            </div>
          )
        })}
      </div>
    </div>
  )
}

