// Shared bullet-card renderer for one section: circular gradient icon
// badge, gradient card background fading from the section color,
// chevron markers, and automatic number-highlighting within each
// bullet so the whole thing reads as a compact, colorful fact-sheet
// rather than a wall of uniform text.
function normalizeBullets(bullets){
  // Defensive normalization: old rows saved before the bullet-array
  // backend migration are still plain strings in the database. Calling
  // .map() directly on a string throws "X.map is not a function" and
  // crashes the entire app (not just this component), confirmed via a
  // real production error report. Some rows also store a JSON-encoded
  // array as a string (e.g. '["Revenue up 10%"]') — parse those so the
  // UI shows real bullets instead of one blob of normal text.
  if (Array.isArray(bullets)) return bullets
  if (typeof bullets === 'string' && bullets.trim()) {
    const raw = bullets.trim()
    if (raw.startsWith('[')) {
      try {
        const parsed = JSON.parse(raw)
        if (Array.isArray(parsed)) return parsed
      } catch (_) { /* fall through */ }
    }
    return [raw]
  }
  return []
}

// Dedicated theme block for PPT / under Market Cap — chips alone were too
// easy to miss; this is a full section with evidence bullets.
function ThemeHighlightSection({themes, intensity, evidence, sourceLabel, compact, feedback}){
  const list = normalizeBullets(themes)
  const evidenceList = normalizeBullets(evidence)
  if (!list.length && !evidenceList.length) return null
  const tone = intensity==='high'?C.green:intensity==='low'?C.muted:C.lime
  return (
    <div style={{
      marginBottom: compact ? 10 : 12,
      background:`linear-gradient(135deg, ${tone}22 0%, ${C.card} 55%)`,
      border:`1px solid ${tone}55`,
      borderRadius:10,padding:compact?'9px 11px':'11px 13px',
      boxShadow:`0 2px 10px ${tone}18`,
    }}>
      <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8,marginBottom:8,flexWrap:'wrap'}}>
        <div style={{display:'flex',alignItems:'center',gap:7}}>
          <div style={{
            width:24,height:24,borderRadius:'50%',flexShrink:0,
            background:`linear-gradient(135deg, ${tone}, ${tone}bb)`,
            display:'flex',alignItems:'center',justifyContent:'center',fontSize:12,
            boxShadow:`0 1px 4px ${tone}66`,
          }}>🌱</div>
          <div>
            <div style={{fontSize:11,fontWeight:900,color:tone,textTransform:'uppercase',letterSpacing:'0.05em'}}>
              Emerging Themes
            </div>
            {sourceLabel && (
              <div style={{fontSize:9,color:C.muted,fontWeight:600,marginTop:1}}>{sourceLabel}</div>
            )}
          </div>
        </div>
        <div style={{display:'flex',alignItems:'center',gap:6,flexShrink:0}}>
          {feedback&&(
            <SectionFeedback
              symbol={feedback.symbol}
              contentType={feedback.contentType}
              sectionKey={feedback.sectionKey||'emerging_themes'}
              sectionLabel="Emerging Themes"/>
          )}
          {intensity && intensity!=='none' && (
            <span style={{
              fontSize:9,fontWeight:800,color:tone,background:tone+'22',
              border:`1px solid ${tone}55`,borderRadius:999,padding:'2px 8px',textTransform:'uppercase',
            }}>
              {intensity} intensity
            </span>
          )}
        </div>
      </div>
      {list.length>0 && (
        <div style={{display:'flex',flexWrap:'wrap',gap:6,marginBottom:evidenceList.length?8:0}}>
          {list.map(t=>(
            <span key={t} style={{
              fontSize:11,fontWeight:800,color:C.text,background:tone+'28',
              border:`1px solid ${tone}66`,borderRadius:999,padding:'4px 11px',
            }}>
              {EMERGING_THEME_LABELS[t]||t}
            </span>
          ))}
        </div>
      )}
      {evidenceList.length>0 && (
        <div style={{display:'flex',flexDirection:'column',gap:4}}>
          <div style={{fontSize:9,fontWeight:800,color:C.muted,textTransform:'uppercase',letterSpacing:'0.04em'}}>
            Theme evidence
          </div>
          {evidenceList.map((b,i)=>(
            <div key={i} style={{display:'flex',gap:6,alignItems:'flex-start'}}>
              <span style={{color:tone,fontSize:10,marginTop:2,flexShrink:0,fontWeight:900}}>›</span>
              <span style={{fontSize:12,lineHeight:1.45,color:C.text}}>
                <HighlightedBullet text={String(b)} color={tone}/>
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

// Sits under Market Cap (above Results/Concall/PPT tabs). Prefers the
// latest PPT themes; then concall; then AI-synced stock_fundamentals so
// every stock can show the same Emerging Themes card over time.
function StockThemesAfterMcap({symbol}){
  const [info, setInfo] = useState(undefined) // undefined=loading, null=none, object=loaded
  useEffect(()=>{
    let cancelled=false
    setInfo(undefined)
    if(!symbol){ setInfo(null); return }
    Promise.all([
      fetchPptSummaries(symbol),
      fetchTranscriptSummaries(symbol),
      fetchStockThemes(symbol),
    ]).then(([ppt, tx, fundThemes])=>{
      if(cancelled) return
      const pptHit = (ppt||[]).find(r=>normalizeBullets(r.emerging_themes).length>0
        || normalizeBullets(r.theme_evidence).length>0)
      const txHit = (tx||[]).find(r=>normalizeBullets(r.emerging_themes).length>0
        || normalizeBullets(r.theme_evidence).length>0)
      if(pptHit || txHit){
        const hit = pptHit || txHit
        const dateLabel = new Date(hit.announced_at).toLocaleDateString('en-IN',
          {day:'numeric', month:'short', year:'numeric'})
        setInfo({
          themes: hit.emerging_themes,
          intensity: hit.theme_intensity,
          evidence: hit.theme_evidence,
          sourceLabel: pptHit
            ? `From PPT · ${dateLabel}`
            : `From Concall · ${dateLabel}`,
        })
        return
      }
      if(fundThemes){
        const srcMap = {ppt:'From PPT', concall:'From Concall', ai_web:'From AI research'}
        const src = srcMap[fundThemes.source] || 'From AI research'
        const dateLabel = fundThemes.at
          ? new Date(fundThemes.at).toLocaleDateString('en-IN',
            {day:'numeric', month:'short', year:'numeric'})
          : null
        setInfo({
          themes: fundThemes.themes,
          intensity: fundThemes.intensity,
          evidence: fundThemes.evidence,
          sourceLabel: dateLabel ? `${src} · ${dateLabel}` : src,
        })
        return
      }
      setInfo(null)
    })
    return()=>{cancelled=true}
  },[symbol])
  if(!info) return null
  return (
    <ThemeHighlightSection
      compact
      themes={info.themes}
      intensity={info.intensity}
      evidence={info.evidence}
      sourceLabel={info.sourceLabel}
      feedback={{symbol, contentType:'themes', sectionKey:'emerging_themes'}}
    />
  )
}

function _feedbackStorageKey(contentType, symbol, sectionKey){
  return `lm_fb_${contentType||''}_${(symbol||'').toUpperCase()}_${sectionKey||''}`
}

/** Compact thumbs up/down — toggle anytime; shows total up/down counts. */
function SectionFeedback({symbol, contentType, sectionKey, sectionLabel}){
  const storageKey = _feedbackStorageKey(contentType, symbol, sectionKey)
  const [vote, setVote] = useState(()=>{
    try{ return localStorage.getItem(storageKey) || null }catch{ return null }
  })
  const [counts, setCounts] = useState({up:0, down:0})
  const [showIssue, setShowIssue] = useState(false)
  const [comment, setComment] = useState('')
  const [sending, setSending] = useState(false)
  const [err, setErr] = useState('')

  const refreshCounts = useCallback(async()=>{
    const map = await fetchContentFeedbackCounts(symbol, contentType, sectionKey)
    const c = map[sectionKey] || {up:0, down:0}
    setCounts({up:c.up||0, down:c.down||0})
  },[symbol, contentType, sectionKey])

  useEffect(()=>{
    try{ setVote(localStorage.getItem(storageKey) || null) }catch{ setVote(null) }
    setShowIssue(false); setComment(''); setErr('')
    refreshCounts()
  },[storageKey, refreshCounts])

  if(!symbol || !contentType || !sectionKey) return null

  function persistVote(v){
    setVote(v)
    try{
      if(v) localStorage.setItem(storageKey, v)
      else localStorage.removeItem(storageKey)
    }catch{/* ignore */}
  }

  async function clearVote(){
    setSending(true); setErr('')
    const prev = vote
    persistVote(null)
    setCounts(c=>({
      up: Math.max(0, c.up - (prev==='up'?1:0)),
      down: Math.max(0, c.down - (prev==='down'?1:0)),
    }))
    const res = await clearContentFeedback({symbol, contentType, sectionKey})
    setSending(false)
    if(res.error){
      setErr(res.error)
      persistVote(prev)
      refreshCounts()
      return
    }
    refreshCounts()
  }

  async function send(v, note){
    setSending(true); setErr('')
    const prev = vote
    const res = await submitContentFeedback({
      symbol, contentType, sectionKey, sectionLabel, vote:v, comment:note,
    })
    setSending(false)
    if(res.error){ setErr(res.error); return }
    persistVote(v)
    setCounts(c=>{
      let up = c.up, down = c.down
      if(prev==='up') up = Math.max(0, up-1)
      if(prev==='down') down = Math.max(0, down-1)
      if(v==='up') up += 1
      if(v==='down') down += 1
      return {up, down}
    })
    setShowIssue(false)
    setComment('')
    refreshCounts()
  }

  async function onUp(){
    if(sending) return
    if(vote==='up') return clearVote()
    return send('up')
  }

  function onDown(){
    if(sending) return
    if(vote==='down') return clearVote()
    setShowIssue(true); setErr('')
  }

  const btn = (active, onClick, Icon, title, activeColor, count)=>(
    <button type="button" title={title} disabled={sending}
      onClick={onClick}
      style={{
        display:'inline-flex',alignItems:'center',justifyContent:'center',gap:3,
        minWidth:26,height:26,borderRadius:7,cursor:sending?'wait':'pointer',
        border:`1px solid ${active?activeColor:C.border}`,
        background:active?activeColor+'22':'transparent',
        color:active?activeColor:C.muted,padding:'0 6px',opacity:sending?0.6:1,
        fontSize:10,fontWeight:700,
      }}>
      <Icon size={13} strokeWidth={2.4}/>
      <span>{count}</span>
    </button>
  )

  return (
    <>
      <div style={{display:'inline-flex',alignItems:'center',gap:4,flexShrink:0}}
        onClick={e=>e.stopPropagation()}>
        {btn(vote==='up', onUp, ThumbsUp, vote==='up'?'Remove helpful':'Helpful', C.green, counts.up)}
        {btn(vote==='down', onDown, ThumbsDown, vote==='down'?'Remove report':'Report issue', C.red, counts.down)}
      </div>
      {showIssue&&(
        <div onClick={()=>{ if(!sending) setShowIssue(false) }}
          style={{position:'fixed',inset:0,zIndex:2100,background:'rgba(0,0,0,0.6)',
            display:'flex',alignItems:'center',justifyContent:'center',padding:20}}>
          <div onClick={e=>e.stopPropagation()}
            style={{background:C.card,borderRadius:14,border:`1px solid ${C.border}`,
              padding:'20px 22px',width:'100%',maxWidth:400,
              boxShadow:'0 20px 50px rgba(0,0,0,0.5)'}}>
            <div style={{fontWeight:800,fontSize:15,color:C.text,marginBottom:4}}>
              What is wrong?
            </div>
            <div style={{fontSize:11.5,color:C.muted,marginBottom:12,lineHeight:1.45}}>
              {symbol} · {sectionLabel||sectionKey}. Tell us what to fix (wrong facts, outdated, unclear…).
            </div>
            <textarea
              value={comment}
              onChange={e=>setComment(e.target.value)}
              rows={4}
              placeholder="Describe the issue…"
              autoFocus
              style={{
                width:'100%',boxSizing:'border-box',resize:'vertical',
                background:C.bg||C.card,color:C.text,border:`1px solid ${C.border}`,
                borderRadius:9,padding:'10px 12px',fontSize:13,lineHeight:1.45,
                outline:'none',marginBottom:8,fontFamily:'inherit',
              }}
            />
            {err&&(
              <div style={{fontSize:11,color:C.red,marginBottom:8}}>{err}</div>
            )}
            <div style={{display:'flex',gap:8}}>
              <button type="button" disabled={sending}
                onClick={()=>send('down', comment)}
                style={{flex:1,padding:'10px 0',borderRadius:9,border:'none',cursor:'pointer',
                  background:C.accent,color:'#000',fontWeight:700,fontSize:13,
                  opacity:sending?0.7:1}}>
                {sending?'Sending…':'Submit issue'}
              </button>
              <button type="button" disabled={sending}
                onClick={()=>setShowIssue(false)}
                style={{padding:'10px 14px',borderRadius:9,border:`1px solid ${C.border}`,
                  cursor:'pointer',background:'transparent',color:C.muted,fontWeight:600,fontSize:12}}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

function BulletSection({icon, label, color, bullets, feedback}){
  const bulletList = normalizeBullets(bullets)
  if (bulletList.length === 0) return null
  return (
    <div style={{
      background:`linear-gradient(135deg, ${color}1a 0%, ${color}05 100%)`,
      border:`1px solid ${color}40`,borderRadius:10,padding:'10px 12px',
      boxShadow:`0 1px 3px ${color}15`,
    }}>
      <div style={{display:'flex',alignItems:'center',gap:7,marginBottom:6}}>
        <div style={{
          width:22,height:22,borderRadius:'50%',flexShrink:0,
          background:`linear-gradient(135deg, ${color}, ${color}bb)`,
          display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,
          boxShadow:`0 1px 4px ${color}66`,
        }}>{icon}</div>
        <span style={{fontSize:10.5,fontWeight:800,color,textTransform:'uppercase',
          letterSpacing:'0.04em',flex:1,minWidth:0}}>{label}</span>
        {feedback&&(
          <SectionFeedback
            symbol={feedback.symbol}
            contentType={feedback.contentType}
            sectionKey={feedback.sectionKey}
            sectionLabel={label}
          />
        )}
      </div>
      <div style={{display:'flex',flexDirection:'column',gap:4}}>
        {bulletList.map((b,i)=>(
          <div key={i} style={{display:'flex',gap:6,alignItems:'flex-start'}}>
            <span style={{color,fontSize:10,marginTop:2,flexShrink:0,fontWeight:900}}>›</span>
            <span style={{fontSize:12.5,lineHeight:1.45,color:C.text}}>
              <HighlightedBullet text={String(b)} color={color}/>
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}

function ReportHistoryPicker({rows, selectedIdx, onSelect}){
  // Lets readers switch among past Concall/PPT summaries for the same
  // symbol (most recent first). Hidden when only one filing exists.
  if (!rows || rows.length <= 1) return null
  return (
    <div style={{display:'flex',flexWrap:'wrap',gap:5,marginBottom:10,alignItems:'center'}}>
      <span style={{fontSize:9,fontWeight:800,color:C.muted,textTransform:'uppercase',letterSpacing:'0.04em'}}>
        History
      </span>
      {rows.map((r, i) => {
        const label = new Date(r.announced_at).toLocaleDateString('en-IN',
          {day:'numeric', month:'short', year:'2-digit'})
        const active = i === selectedIdx
        return (
          <button key={r.attachment_url || i} type="button" onClick={()=>onSelect(i)}
            title={`Read report filed ${label}`}
            style={{
              fontSize:10,fontWeight:active?800:600,cursor:'pointer',
              padding:'3px 8px',borderRadius:999,
              border:`1px solid ${active?C.accent:C.border}`,
              background:active?C.accent+'22':C.card,
              color:active?C.accent:C.muted,
            }}>
            {label}
          </button>
        )
      })}
    </div>
  )
}

function TranscriptSummary({symbol}){
  const [rows, setRows] = useState(null) // null=loading, []=none, array=loaded
  const [showFull, setShowFull] = useState(false)
  const [selectedIdx, setSelectedIdx] = useState(0)
  useEffect(() => {
    let cancelled = false
    setRows(null)
    setShowFull(false)
    setSelectedIdx(0)
    if (!symbol) return
    fetchTranscriptSummaries(symbol).then(r => { if (!cancelled) setRows(r) })
    return () => { cancelled = true }
  }, [symbol])

  if (rows === null) {
    return (
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:'20px 14px',
        textAlign:'center',color:C.muted,fontSize:12}}>
        Loading concall report…
      </div>
    )
  }
  if (rows.length === 0) {
    return (
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:'20px 14px',
        textAlign:'center'}}>
        <div style={{fontSize:13,fontWeight:700,color:C.text,marginBottom:6}}>No concall report yet</div>
        <div style={{fontSize:11.5,color:C.muted,lineHeight:1.5}}>
          When an earnings-call transcript is filed for {symbol}, the server will read it and generate a simple report here.
        </div>
      </div>
    )
  }

  const latest = rows[Math.min(selectedIdx, rows.length-1)]
  const dateLabel = new Date(latest.announced_at).toLocaleDateString('en-IN',
    {day:'numeric', month:'short', year:'numeric'})
  const sections = showFull ? TRANSCRIPT_FULL_SECTIONS : TRANSCRIPT_SIMPLE_SECTIONS
  const hasMoreSections = TRANSCRIPT_FULL_SECTIONS.some(s => {
    if (TRANSCRIPT_SIMPLE_SECTIONS.some(ss => ss.key === s.key)) return false
    return normalizeBullets(latest[s.key]).length > 0
  })

  return (
    <div style={{
      background:C.card,border:`1px solid ${C.border}`,borderRadius:12,overflow:'hidden',
      boxShadow:'0 2px 12px rgba(0,0,0,0.25)',
    }}>
      <div style={{height:4,background:`linear-gradient(90deg, ${C.purple}, ${C.blue}, ${C.teal}, ${C.green})`}}/>
      <div style={{padding:'12px 14px'}}>
        <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:8,gap:8}}>
          <div style={{fontSize:12,fontWeight:900,color:C.text,display:'flex',alignItems:'center',gap:6}}>
            <span style={{fontSize:15}}>🎙️</span> Concall Report
          </div>
          <div style={{fontSize:10,color:C.muted,flexShrink:0,fontWeight:600}}>{dateLabel}</div>
        </div>
        <ReportHistoryPicker rows={rows} selectedIdx={selectedIdx}
          onSelect={i=>{ setSelectedIdx(i); setShowFull(false) }}/>
        <StatusChips guidance={latest.guidance_direction} tone={latest.management_tone}/>
        <ThemeHighlightSection
          themes={latest.emerging_themes}
          intensity={latest.theme_intensity}
          evidence={latest.theme_evidence}
          sourceLabel="Highlighted from this concall"
          feedback={{symbol, contentType:'concall', sectionKey:'emerging_themes'}}
        />
        {latest.overall_summary && (
          <div style={{marginBottom:12}}>
            <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8,marginBottom:4}}>
              <div style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:'uppercase',
                letterSpacing:'0.04em'}}>Summary</div>
              <SectionFeedback symbol={symbol} contentType="concall" sectionKey="overall_summary"
                sectionLabel="Summary"/>
            </div>
          <div style={{
              borderLeft:`3px solid ${C.accent}`,paddingLeft:10,
            fontSize:12.5,lineHeight:1.6,color:C.text,
          }}>{latest.overall_summary}</div>
          </div>
        )}
        <div style={{display:'flex',flexDirection:'column',gap:7}}>
          {sections.map(s=>(
            <React.Fragment key={s.key}>
              <BulletSection icon={s.icon} label={s.label} color={s.color} bullets={latest[s.key]}
                feedback={{symbol, contentType:'concall', sectionKey:s.key}}/>
              {/* Watch Next sits right after Outlook — action list near forward view */}
              {s.key==='outlook_guidance' && (
                <BulletSection icon="👁️" label="Watch Next" color={C.accent} bullets={latest.watch_next}
                  feedback={{symbol, contentType:'concall', sectionKey:'watch_next'}}/>
              )}
            </React.Fragment>
          ))}
        </div>
        <div style={{display:'flex',gap:12,marginTop:10,flexWrap:'wrap',alignItems:'center'}}>
          {(hasMoreSections || showFull) && (
            <span onClick={()=>setShowFull(v=>!v)}
              style={{fontSize:10,fontWeight:700,color:C.accent,cursor:'pointer'}}>
              {showFull ? 'Show simple report' : 'Show full report'}
            </span>
          )}
          {latest.attachment_url&&(
            <a href={latest.attachment_url} target="_blank" rel="noopener noreferrer"
              style={{fontSize:10,fontWeight:700,color:C.accent}}>View original transcript ↗</a>
          )}
        </div>
        <div style={{fontSize:9,color:C.muted,marginTop:8,fontStyle:'italic'}}>
          AI-generated summary of the earnings call transcript — paraphrased, may miss nuance. Not investment advice.
        </div>
      </div>
    </div>
  )
}

