  // most of these checks will find nothing new; this trades some
  // extra, mostly-empty checks for not missing a new announcement by
  // more than a minute once the backend does have one.
  useEffect(()=>{
    if(!session) return
    const checkAnnouncementAlerts = async()=>{
      try{
        const since = lastAnnouncementCheck.current || new Date(Date.now()-90000).toISOString()
        const {data} = await supabase
          .from('corporate_announcements')
          .select('*')
          .gte('created_at', since)
          .order('created_at', {ascending:false})
          .limit(10)

        lastAnnouncementCheck.current = new Date().toISOString()

        if(data && data.length > 0){
          const prefs=alertPrefsRef.current
          if(prefs.announcements===false) return
          const wlOnly=prefs.watchlistOnly===true
          const wlSyms=watchlistAlertSymsRef.current
          let playedSound=false
          data.forEach(ann=>{
            if(!isAnnouncementAlertEnabled(ann, prefs)) return
            if(wlOnly){
              const sym=String(ann.symbol||'').toUpperCase()
              if(!sym || !wlSyms.has(sym)) return
            }
            if(!playedSound){ playAlertSoundFromPrefs(prefs); playedSound=true }
            const cat=classifyAnnouncementAlert(ann)
            const title=`📢 ${ann.symbol} — ${cat.label}`
            const body=ann.subject.length>110 ? ann.subject.slice(0,107)+'…' : ann.subject
            const historyEntry={
              id:`ann-${ann.symbol}-${ann.id||ann.announced_at||ann.created_at}`,
              at: ann.created_at || ann.announced_at || new Date().toISOString(),
              kind:'announcement',
              sym: ann.symbol,
              title,
              body,
              category: cat.label,
            }
            pushNotifHistory(historyEntry)
            showInAppAlert(historyEntry)
            if(typeof Notification==='undefined' || Notification.permission!=='granted') return
            const n=new Notification(title,{
                body,
                icon: '/favicon.ico',
                tag: `announcement-${ann.symbol}-${ann.id}`,
                requireInteraction: false,
                silent: prefs.soundEnabled!==false,
              }
            )
            n.onclick = ()=>{
              window.focus()
              setMainTab('announcements')
              if(ann.symbol) openChart(ann.symbol)
            }
            setTimeout(()=>n.close(), 8000)
          })
        }
      }catch(e){
        console.warn('Announcement alert check failed:', e.message)
      }
    }

    checkAnnouncementAlerts()
    const timer = setInterval(checkAnnouncementAlerts, 60000)
    return ()=>clearInterval(timer)
  },[session,showInAppAlert])
  const [chartWide,setChartWide]=useState(()=>loadChartPanelAutoSave().chart_wide) // 0=normal 1=wide 2=extra-wide
  // Drag-to-resize divider between the table and chart panel — continuous
  // resize in addition to the existing 3-preset expand button. null means
  // "use the chartWide preset"; once dragged, holds the chart's exact
  // width % and takes over from the preset until the chart is closed.
  const [chartPanelPct,setChartPanelPct]=useState(()=>loadChartPanelAutoSave().chart_panel_pct)
  const [isDraggingDivider,setIsDraggingDivider]=useState(false)
  // Three-column layout (RS | Chart | Fund): drag handles between panes.
  const [colWidths,setColWidths]=useState(()=>loadColWidths())
  const [colDrag,setColDrag]=useState(null) // {leftId, rightId} | null
  /**
   * ↗ beside a symbol — open that company's detailed page in its own
   * Fundamentals section (third full-height column). Does not change the
   * "follow every tape click" preference for Fundamentals.
   */
  const openCompanyPage=useCallback((sym)=>{
    if(!sym) return
    setChartDetailTabHint('about')
    openChart(sym,{isIndex:false})
    if(isMobile) return
    // Columns layout only applies on RS Rating — land there so Fundamentals
    // can sit as its own full-height section beside Chart and RS.
    if(mainTab!=='rs') setMainTab('rs')
    applyDockLayout({ mode:'columns', order:['chart','screener','detail'] })
    const companyCols = { chart:50, screener:25, detail:25 }
    setColWidths(companyCols)
    persistColWidths(companyCols)
    setPanelWins(w=>({
      ...w,
      chart:{...(w.chart||{}),open:true,minimized:false},
      detail:{...(w.detail||{}),open:true,minimized:false},
    }))
  },[openChart,isMobile,mainTab])
  const innerRowRef=useRef(null)
  const chartWideRef=useRef(chartWide)
  const chartPanelPctRef=useRef(chartPanelPct)
  const colWidthsRef=useRef(colWidths)
  const colDragLastXRef=useRef(null)
  chartWideRef.current=chartWide
  chartPanelPctRef.current=chartPanelPct
  colWidthsRef.current=colWidths
  const chartOnLeftRef=useRef(false)
  chartOnLeftRef.current=dockLayout.order.indexOf('chart') < dockLayout.order.indexOf('screener')
  const persistChartPanelState=(wide,pct)=>{
    persistChartPanelAutoSave(wide,pct)
  }
  useEffect(()=>{
    if(!isDraggingDivider)return
    const onMove=(e)=>{
      if(!innerRowRef.current)return
      const rect=innerRowRef.current.getBoundingClientRect()
      const relX=e.clientX-rect.left
      const chartPct=chartOnLeftRef.current
        ?(relX/rect.width)*100
        :((rect.width-relX)/rect.width)*100
      setChartPanelPct(Math.min(85,Math.max(15,chartPct)))
    }
    const onUp=()=>{
      setIsDraggingDivider(false)
      persistChartPanelState(chartWideRef.current,chartPanelPctRef.current)
    }
    window.addEventListener('pointermove',onMove)
    window.addEventListener('pointerup',onUp)
    window.addEventListener('pointercancel',onUp)
    return()=>{
      window.removeEventListener('pointermove',onMove)
      window.removeEventListener('pointerup',onUp)
      window.removeEventListener('pointercancel',onUp)
    }
  },[isDraggingDivider])
  useEffect(()=>{
    if(!colDrag) return
    colDragLastXRef.current=null
    const onMove=(e)=>{
      if(!innerRowRef.current)return
      const rect=innerRowRef.current.getBoundingClientRect()
      if(rect.width<=0)return
      if(colDragLastXRef.current==null){
        colDragLastXRef.current=e.clientX
        return
      }
      const dPct=((e.clientX-colDragLastXRef.current)/rect.width)*100
      colDragLastXRef.current=e.clientX
      const {leftId,rightId}=colDrag
      setColWidths(w=>{
        const left=w[leftId]??33, right=w[rightId]??33
        const pair=left+right
        const MIN=15
        let nl=left+dPct
        nl=Math.max(MIN, Math.min(pair-MIN, nl))
        return {...w, [leftId]:nl, [rightId]:pair-nl}
      })
    }
    const onUp=()=>{
      setColDrag(null)
      persistColWidths(colWidthsRef.current)
    }
    window.addEventListener('pointermove',onMove)
    window.addEventListener('pointerup',onUp)
    window.addEventListener('pointercancel',onUp)
    return()=>{
      window.removeEventListener('pointermove',onMove)
      window.removeEventListener('pointerup',onUp)
      window.removeEventListener('pointercancel',onUp)
    }
  },[colDrag])
  const [rsPage,setRsPage]=useState(0)
  const RS_PAGE_SIZE=25
  const [ppFilter52WL,setPpFilter52WL]=useState('all')
  const [ppFilterWeak,setPpFilterWeak]=useState('all')

  // Shared market cap check, used everywhere a stock list gets filtered
  // (RS Rating's rsBase above, and the Breakout tab's sections below) so
  // the filter is consistent across tabs, not just the main scanner.
  const passesMcap = s => (mcapMin===''||(s.marketCap??-1)>=+mcapMin) && (mcapMax===''||(s.marketCap??Infinity)<=+mcapMax)
  // Used by the multi-select Signal filter (OR logic — a stock matches
  // if it satisfies ANY of the selected signals).
  const matchesSignal = (s,sig) => {
    if(sig==='pp') return topVolumeSignal(s)==='pp'
    if(sig==='bullsnort') return !!s.isBullSnort
    if(sig==='hy') return topVolumeSignal(s)==='hy'
    if(sig==='ht') return topVolumeSignal(s)==='ht'
    if(sig==='ema5') return !!s.nearEMA5?.isNearEMA5
    if(sig==='ema9') return !!s.nearEMA9?.isNearEMA9
    if(sig==='ema21') return !!s.nearEMA21?.isNearEMA21
    if(sig==='ema50') return !!s.nearEMA50?.isNearEMA50
    if(sig==='power') return topVolumeSignal(s)==='pp' && s.rs>=80
    if(sig==='ibv') return topVolumeSignal(s)==='ibv'
    if(sig==='r1breakout') return !!s.isResistanceBreakout
    if(sig==='cupbreakout') return !!s.isCupHandleBreakout
    if(sig==='guppy') return !!s.isGuppyBullishCrossover
    if(sig==='52wh') return !!s.is52whBreakout
    if(sig==='hyht') return !!calcHYHTBreakout(s).isBreakout
    if(sig==='volpull') return !!calcVolClimaxNearSupport(s).isMatch
    if(sig==='hyema9') return !!calcHyLowVolEma9Bounce(s).isMatch
    if(sig==='s2new') return !!s.isS2NewEntry
    if(sig==='vcp2t') return !!s.isVCP && s.vcpStage===2
    if(sig==='vcp3t') return !!s.isVCP && s.vcpStage===3
    if(sig==='vcp4t') return !!s.isVCP && s.vcpStage===4
    if(sig==='ppconsec2') return hasConsecutivePP(s.pp?.ppHistory, 2)
    if(sig==='ppgt2') return (s.pp?.ppCount10d||0) > 2
    return false
  }
  // Does one stock satisfy a *saved* scanner's stored filter object? Mirrors
  // the rsBase predicate, but reads every criterion from `f` instead of the
  // live filter state so alerts can evaluate scanners the user isn't
  // currently looking at.
  const matchesSavedScanner = (s, f) => {
    if(!s || !f) return false
    if(f.sectorFilter&&f.sectorFilter!=='all'&&s.sector!==f.sectorFilter) return false
    if(f.industryFilter&&f.industryFilter!=='all'&&s.industry!==f.industryFilter) return false
    if(f.search&&!stockMatchesQuery(s, f.search)) return false
    const lo=f.rsMin??0, hi=f.rsMax??99
    if(s.rs<lo||s.rs>hi) return false
    if(f.mcapMin!==''&&f.mcapMin!=null&&(s.marketCap==null||s.marketCap<+f.mcapMin)) return false
    if(f.mcapMax!==''&&f.mcapMax!=null&&(s.marketCap==null||s.marketCap>+f.mcapMax)) return false
    if(f.rsImprFilter&&f.rsImprFilter!=='all'&&s.rsTrend?.trend!==f.rsImprFilter) return false
    const sigs=Array.isArray(f.sigFilters)
      ? f.sigFilters
      : (f.sigFilter&&f.sigFilter!=='all'?[f.sigFilter]:[])
    if(sigs.length>0&&!sigs.some(sig=>matchesSignal(s,sig))) return false
    if(f.stageFilter&&f.stageFilter!=='all'&&calcWeinsteinStage(s).stage!==+f.stageFilter) return false
    const p=f.presetFilter||'all'
    if(p==='pp'&&!s.pp?.isPP) return false
    if(p==='bullsnort'&&!s.isBullSnort) return false
    if(p==='ema5'&&!s.nearEMA5?.isNearEMA5) return false
    if(p==='ema9'&&!s.nearEMA9?.isNearEMA9) return false
    if(p==='hy'&&!s.hy?.isHY) return false
    if(p==='ht'&&!s.ht?.isHT) return false
    if(p==='rs90'&&(s.rsTv??s.rs)<90) return false
    if(p==='rs80'&&(s.rsTv??s.rs)<80) return false
    if(p==='impr'&&s.rsTrend?.trend!=='improving') return false
    if(p==='power'&&!(s.pp?.isPP&&s.rs>=80)) return false
    if(p==='s2'&&calcWeinsteinStage(s).stage!==2) return false
    if(p==='s1'&&calcWeinsteinStage(s).stage!==1) return false
    if(p==='s3'&&calcWeinsteinStage(s).stage!==3) return false
    if(p==='s4'&&calcWeinsteinStage(s).stage!==4) return false
    if(p==='surge'&&(s.hy?.pctOfMax||0)<95) return false
    if(p==='ibv'&&!calcIBV(s).isIBV) return false
    if(p==='breakout'&&!calcHYHTBreakout(s).isBreakout) return false
    if(p==='volpull'&&!calcVolClimaxNearSupport(s).isMatch) return false
    if(p==='hyema9'&&!calcHyLowVolEma9Bounce(s).isMatch) return false
    if(p==='canslim'&&!s.isCanslim) return false
    if(p==='pead'&&!s.isPead) return false
    const rating=resultRatingsMap[String(s.sym||'').toUpperCase()]||null
    if(p==='resultAny'&&!rating) return false
    if(p==='resultEx'&&rating!=='Excellent') return false
    if(p==='resultGood'&&rating!=='Good') return false
    if(p==='resultNeu'&&rating!=='Neutral') return false
    if(p==='resultWeak'&&rating!=='Weak') return false
    const rr=Array.isArray(f.resultRatingFilters)?f.resultRatingFilters:[]
    if(rr.length>0){
      const wantsHas=rr.includes('has')
      const opts=rr.filter(x=>x!=='has')
      if(!((wantsHas&&!!rating)||(opts.length>0&&opts.includes(rating)))) return false
    }
    const fr=Array.isArray(f.fundRatingFilters)?f.fundRatingFilters:[]
    if(fr.length>0){
      const label=ensureFundamentalQuality(s).label
      if(!label||!fr.includes(label)) return false
    }
    const st=Array.isArray(f.strategyFilters)?f.strategyFilters:[]
    if(st.length>0&&!st.some(x=>(x==='pead'&&s.isPead)||(x==='canslim'&&s.isCanslim))) return false
    const bt=f.breakoutTypeFilter
    if(bt==='hyht'&&!calcHYHTBreakout(s).isBreakout) return false
    if(bt==='volpull'&&!calcVolClimaxNearSupport(s).isMatch) return false
    if(bt==='hyema9'&&!calcHyLowVolEma9Bounce(s).isMatch) return false
    if(bt==='ema5'&&!s.nearEMA5?.isNearEMA5) return false
    if(bt==='r1'&&!s.isResistanceBreakout) return false
    if(bt==='52wh'&&!s.is52whBreakout) return false
    if(bt==='cup'&&!s.isCupHandleBreakout) return false
    if(bt==='guppy'&&!s.isGuppyBullishCrossover) return false
    if(bt==='s2'&&!s.isS2NewEntry) return false
    return true
  }
